        "everyday|2:1|5|l3": "হ্যাঁ, দয়া করে। ওঁকে গোয়া ট্রিপের ব্যাপারে আমাকে ফোন করতে বলবেন?",
        "everyday|2:1|5|l4": "মাফ করবেন, লাইনটা খুব খারাপ। আর একবার বলবেন?",
        "everyday|2:1|5|l5": "নিশ্চয়ই। দয়া করে মিস্টার কামাথকে গোয়া ট্রিপের ব্যাপারে আমাকে ফোন করতে বলবেন।",
        "everyday|2:1|5|l6": "অবশ্যই। কোন নম্বরে আপনাকে পাওয়া সবচেয়ে সুবিধা?",
        "everyday|2:1|5|l7": "আমাকে ৯৮৪৫০ ১২৩৭৬ নম্বরে পাবেন।",
        "everyday|2:1|5|l8": "একবার পড়ে শোনাই: ৯৮৪৫০ ১২৩৭৬। আমি নিশ্চিত করব যাতে উনি মেসেজটা পান।",
        "everyday|2:1|5|l9": "হ্যাঁ, ঠিক। আপনার সাহায্যের জন্য অনেক ধন্যবাদ।",
        "everyday|2:1|5|q0": "অনিল কেন মিস্টার কামাথের সঙ্গে কথা বলতে পারছে না?",
        "everyday|2:1|5|q0o0": "উনি চারটে পর্যন্ত অফিসের বাইরে",
        "everyday|2:1|5|q0o1": "উনি অন্য একটা ফোনে ব্যস্ত",
        "everyday|2:1|5|q0o2": "উনি কোম্পানি ছেড়ে দিয়েছেন",
        "everyday|2:1|5|q0o3": "উনি গোয়ায় ছুটি কাটাচ্ছেন",
        "everyday|2:1|5|q1": "অনিলের মেসেজটা কী নিয়ে?",
        "everyday|2:1|5|q1o0": "গোয়া ট্রিপ",
        "everyday|2:1|5|q1o1": "ব্যাংক লোন",
