        "everyday|3:1|1|p0": "আমি আমার মেয়ের নামে একটা সেভিংস অ্যাকাউন্ট খুলতে চাই।",
        "everyday|3:1|1|p1": "নগদ টাকা জমা দিতে চাইলে দয়া করে এই স্লিপটা পূরণ করুন।",
        "everyday|3:1|1|p2": "চেক ছাড়া এক দিনে আমি কত টাকা তুলতে পারি?",
        "everyday|3:1|1|p3": "দয়া করে আমার পাসবইটা আপডেট করে দেবেন? অনেক মাস ধরে ছাপা হয়নি।",
        "everyday|3:1|1|p4": "আমার ব্যালান্স বেশ কম, তাই ভয় হচ্ছে চেকটা বাউন্স করতে পারে।",
        "everyday|3:1|2|w0": "এটিএম",
