        "everyday|3:1|3|p0": "এটিএম আমার ডেবিট কার্ডটা আটকে রেখেছে, তাই এখনই ওটা ব্লক করাতে হবে।",
        "everyday|3:1|3|p1": "কেউ নিজেকে ব্যাংকের লোক বললেও কখনও কাউকে নিজের পিন বলবেন না।",
        "everyday|3:1|3|p2": "আমি ইউপিআই দিয়ে ভাড়া দিয়েছি, কিন্তু এখনও বাড়িওয়ালার কাছে পৌঁছায়নি।",
        "everyday|3:1|3|p3": "দুই বছরের ফিক্সড ডিপোজিটে আপনারা কত হারে সুদ দেন?",
        "everyday|3:1|3|p4": "দয়া করে আধার আর প্যান দিয়ে আপনার কেওয়াইসি সম্পূর্ণ করুন, নইলে অ্যাকাউন্ট বন্ধ হয়ে যেতে পারে।",
        "everyday|3:1|4|title": "প্রথম ব্যাংক অ্যাকাউন্ট",
        "everyday|3:1|4|text": "সঞ্জনা ম্যাঙ্গালুরুতে তার প্রথম চাকরি পেল, আর স্যালারি অ্যাকাউন্ট খুলতে কাছের একটা ব্যাংকে গেল। কেওয়াইসি-র জন্য অফিসার তার আধার কার্ড, প্যান কার্ড আর দুটো ছবি চাইলেন। সঞ্জনা ফর্ম পূরণ করে দু'হাজার টাকা জমা দিল। এক সপ্তাহ পরে সে একটা পাসবই, একটা চেকবই আর একটা ডেবিট কার্ড পেল। অফিসার তাকে এটিএম-এ গিয়ে নতুন পিন সেট করতে বললেন, আর বললেন কখনও যেন কাউকে সেটা না বলে। সে ফোনে অ্যাকাউন্টটা ইউপিআই-এর সঙ্গেও জুড়ে নিল। এখন সে প্রতি মাসে ব্যালান্স দেখে, আর সুদ পাওয়ার জন্য কিছু টাকা ফিক্সড ডিপোজিটে রাখে।",
        "everyday|3:1|4|q0": "সঞ্জনা কেন অ্যাকাউন্ট খুলেছিল?",
        "everyday|3:1|4|q0o0": "মাইনে পাওয়ার জন্য",
        "everyday|3:1|4|q0o1": "লোন নেওয়ার জন্য",
