        "everyday|3:1|4|q2o3": "রোজ বদলাও",
        "everyday|3:1|5|title": "একটা ব্যর্থ পেমেন্ট",
        "everyday|3:1|5|scenario": "একটা ইউপিআই পেমেন্ট ব্যর্থ হওয়ায় ফারহান পুনেতে তার ব্যাংকে যায়, আর হেল্প ডেস্কে ঋতুর সঙ্গে কথা বলে।",
        "everyday|3:1|5|l0": "সুপ্রভাত, স্যার। আজ আপনাকে কীভাবে সাহায্য করতে পারি?",
        "everyday|3:1|5|l1": "সুপ্রভাত। কাল আমি ইউপিআই দিয়ে তিন হাজার টাকা পাঠিয়েছিলাম, কিন্তু পেমেন্টটা ব্যর্থ হয়েছে।",
        "everyday|3:1|5|l2": "বুঝলাম। টাকাটা কি আপনার অ্যাকাউন্ট থেকে কেটে নেওয়া হয়েছে?",
        "everyday|3:1|5|l3": "হ্যাঁ। আমার ব্যালান্স কমে গেছে, কিন্তু দোকান টাকাটা পায়নি।",
        "everyday|3:1|5|l4": "চিন্তা করবেন না। ব্যর্থ পেমেন্টের টাকা সাধারণত তিন কাজের দিনের মধ্যে ফিরে আসে।",
        "everyday|3:1|5|l5": "যাক, নিশ্চিন্ত হলাম। এখানে যখন এসেইছি, এডুকেশন লোনের ব্যাপারে একটু বলবেন?",
        "everyday|3:1|5|l6": "অবশ্যই। সুদের হার মোটামুটি ন'শতাংশ, আর আপনার কেওয়াইসি হালনাগাদ থাকা চাই।",
        "everyday|3:1|5|l7": "মনে হয় ওটা সম্পূর্ণ আছে। গত বছর আমি আধারের তথ্য আপডেট করেছিলাম।",
        "everyday|3:1|5|l8": "একটু দেখে নিই। হ্যাঁ, সব ঠিক আছে। এই নিন লোনের ফর্ম আর কাগজপত্রের একটা তালিকা।",
        "everyday|3:1|5|l9": "অনেক ধন্যবাদ। আপনি খুব সাহায্য করলেন।",
        "everyday|3:1|5|q0": "ফারহানের পেমেন্টে কী গোলমাল হয়েছিল?",
        "everyday|3:1|5|q0o0": "পেমেন্ট ব্যর্থ হয়েছিল, কিন্তু অ্যাকাউন্ট থেকে টাকা কেটে গিয়েছিল",
