        "everyday|4:1|0|w5": "ন্যাপকিন",
        "everyday|4:1|1|p0": "শুনছেন, আমাদের মেনুটা আর একটু জল দেবেন?",
        "everyday|4:1|1|p1": "ওয়েটার নীর দোসা খেতে বললেন, তাই আমরা দু'প্লেট অর্ডার করলাম।",
        "everyday|4:1|1|p2": "একটা স্টার্টার ভাগ করে খাই, তারপর যে যার মেন কোর্স অর্ডার করি?",
        "everyday|4:1|1|p3": "পেট এত ভরা যে মিষ্টি আর খেতে পারব না, তবে একটা ফিল্টার কফি পেলে খুব ভালো হয়।",
        "everyday|4:1|1|p4": "আমাদের আরও কয়েকটা ন্যাপকিন আর আমার ছেলের জন্য একটা ছোট চামচ এনে দেবেন?",
