        "everyday|4:1|3|p0": "আমার বাদামে অ্যালার্জি আছে, তাই এই তরকারির উপকরণগুলো একটু দেখে নেবেন?",
        "everyday|4:1|3|p1": "আমরা সবাই নিরামিষ খাই, তাই দয়া করে খেয়াল রাখবেন কোনো কিছুতে যেন ডিম না থাকে।",
        "everyday|4:1|3|p2": "একটু কম ঝাল করে দেবেন? আমার ছেলে বেশি লঙ্কা খেতে পারে না।",
        "everyday|4:1|3|p3": "এখানে খাবারের পরিমাণ বিশাল, তাই বাকিটা পার্সেল করে দেবেন?",
        "everyday|4:1|3|p4": "বিলে আগে থেকেই সার্ভিস চার্জ ধরা আছে, তাই বকশিশ দেওয়ার দরকার নেই।",
        "everyday|4:1|4|title": "উডুপিতে জন্মদিনের ডিনার",
        "everyday|4:1|4|text": "ঠাকুমার আশিতম জন্মদিনে কিরণ উডুপির একটা জনপ্রিয় রেস্তোরাঁয় টেবিল বুক করল। ওয়েটার মেনু নিয়ে এলেন আর স্টার্টার হিসেবে পনির টিক্কা খেতে বললেন। কিরণের খুড়তুতো বোন নিশার চিনেবাদামে অ্যালার্জি আছে, তাই কিরণ ওয়েটারকে প্রতিটা পদ ভালো করে দেখে নিতে বলল। ঠাকুমা তাঁর মেন কোর্স কম ঝাল চাইলেন, আর রাঁধুনি খুশি মনে রাজি হলেন। শেষপাতে পুরো পরিবার মিলে একটা বিশাল গাদবাদ আইসক্রিম ভাগ করে খেল। বিল আসার পর কিরণ দেখল যে পাঁচ শতাংশ সার্ভিস চার্জ আগে থেকেই ধরা আছে। তবুও সে অল্প বকশিশ দিল, কারণ ওয়েটার তাদের সঙ্গে খুব ধৈর্য ধরে ব্যবহার করেছিলেন। বেঁচে যাওয়া রুটিগুলো তারা পার্সেল করে বাড়ি নিয়ে গেল।",
        "everyday|4:1|4|q0": "কিরণ কেন ওয়েটারকে প্রতিটা পদ দেখে নিতে বলেছিল?",
        "everyday|4:1|4|q0o0": "তার খুড়তুতো বোনের চিনেবাদামে অ্যালার্জি আছে",
