        "everyday|4:1|5|scenario": "অনন্যা আর তার এক বন্ধু পুনের একটা রেস্তোরাঁয় বসে আছে। ওয়েটার মনোজ অর্ডার নিতে আসেন।",
        "everyday|4:1|5|l0": "শুভ সন্ধ্যা, ম্যাডাম। অর্ডার দেবেন, নাকি আর কয়েক মিনিট লাগবে?",
        "everyday|4:1|5|l1": "মনে হয় আমরা তৈরি। আজকের স্পেশাল কী?",
        "everyday|4:1|5|l2": "আজ আছে মালভানি মাছের ঝোল আর একটা নিরামিষ থালি।",
        "everyday|4:1|5|l3": "আমার বন্ধুর জন্য একটা থালি দিন। মাছের ঝোলটা কি খুব ঝাল?",
        "everyday|4:1|5|l4": "বেশ ঝাল, তবে আপনি চাইলে শেফ কম ঝাল করে দিতে পারেন।",
        "everyday|4:1|5|l5": "হ্যাঁ, কম ঝাল করে দিন। আর আমার বন্ধুর বাদামে অ্যালার্জি আছে, তাই থালিতে কাজু দেবেন না।",
        "everyday|4:1|5|l6": "নিশ্চয়ই, আমি রান্নাঘরে বলে দিচ্ছি। সঙ্গে কিছু পানীয় নেবেন?",
        "everyday|4:1|5|l7": "দুটো মিষ্টি লস্যি দিন। আর শেষে কি ইউপিআই দিয়ে পেমেন্ট করা যাবে?",
        "everyday|4:1|5|l8": "অবশ্যই, আমরা ইউপিআই আর কার্ড দুটোই নিই। আমি এক্ষুনি আপনাদের পানীয় নিয়ে আসছি।",
        "everyday|4:1|5|l9": "ধন্যবাদ, আপনি খুব ভালো।",
        "everyday|4:1|5|q0": "আজকের স্পেশাল কী কী?",
        "everyday|4:1|5|q0o0": "মালভানি মাছের ঝোল আর একটা নিরামিষ থালি",
