        "everyday|5:1|1|p0": "আমি পাঁচই মার্চ থেকে দু'রাতের জন্য একটা বুকিং করতে চাই।",
        "everyday|5:1|1|p1": "এই সপ্তাহান্তে একটা ডাবল রুম খালি আছে কি না একটু দেখবেন?",
        "everyday|5:1|1|p2": "চেক-ইন দুপুর বারোটায়, তবে আপনি আগেই আমাদের কাছে ব্যাগ রেখে যেতে পারেন।",
        "everyday|5:1|1|p3": "একটু দেরিতে চেক-আউট করা কি সম্ভব? আমাদের ট্রেন ছ'টায় ছাড়বে।",
        "everyday|5:1|1|p4": "আপনার ট্যাক্সিচালক লবিতে আপনার জন্য অপেক্ষা করছেন।",
