        "everyday|5:1|2|w5": "রুম সার্ভিস",
        "everyday|5:1|3|p0": "দয়া করে দুটো পরিষ্কার তোয়ালে আর একটা বাড়তি বালিশ ওপরে পাঠিয়ে দেবেন?",
        "everyday|5:1|3|p1": "দুঃখের কথা, ২০৪ নম্বর ঘরের এসিটা একদম চলছে না।",
        "everyday|5:1|3|p2": "হাউসকিপিং এখনও আমাদের ঘর পরিষ্কার করেনি, অথচ তিনটে বেজে গেছে।",
        "everyday|5:1|3|p3": "আমি অভিযোগ করতে চাই না, কিন্তু ঘরটায় খুব আওয়াজ।",
        "everyday|5:1|3|p4": "রাত এগারোটার পরেও কি রুম সার্ভিস পাওয়া যায়, নাকি তখন রান্নাঘর বন্ধ হয়ে যায়?",
        "everyday|5:1|4|title": "মাদিকেরিতে এক হট্টগোলের রাত",
        "everyday|5:1|4|text": "নিখিল আর তার স্ত্রী শ্রেয়া লম্বা উইকেন্ডের জন্য মাদিকেরির একটা ছোট হোটেলে বুকিং করেছিল। চেক-ইনের সময় রিসেপশনিস্ট তাদের একতলায় একটা ডাবল রুম দিলেন। সেই রাতে এসিটা জোরে খটখট আওয়াজ করছিল, আর ঘরটা এত গরম ছিল যে ঘুমোনো যাচ্ছিল না। নিখিল ফ্রন্ট ডেস্কে ফোন করে ভদ্রভাবে অভিযোগ জানাল। ম্যানেজার দুঃখপ্রকাশ করে তাদের ওপরতলায় পাহাড়ের দৃশ্যওয়ালা একটা শান্ত ঘরে সরিয়ে দিলেন। পরদিন সকালে না চাইতেই হাউসকিপিং পরিষ্কার তোয়ালে আর বাড়তি বালিশ দিয়ে গেল। চেক-আউটের সময় অসুবিধার ক্ষতিপূরণ হিসেবে ম্যানেজার তাদের বিনামূল্যে ব্রেকফাস্ট দিলেন।",
        "everyday|5:1|4|q0": "প্রথম ঘরটায় কী সমস্যা ছিল?",
