        "everyday|5:1|5|scenario": "সন্ধেবেলা রাহুল হুব্বল্লির একটা হোটেলে পৌঁছায়, আর ফ্রন্ট ডেস্কে ফারাহ তার চেক-ইন করায়।",
        "everyday|5:1|5|l0": "শুভ সন্ধ্যা, স্যার, হোটেল সঙ্গমে আপনাকে স্বাগত। আমাদের এখানে কি আপনার বুকিং আছে?",
        "everyday|5:1|5|l1": "হ্যাঁ, রাহুল যোশীর নামে, তিন রাতের জন্য।",
        "everyday|5:1|5|l2": "হ্যাঁ, দেখতে পাচ্ছি: শুক্রবার পর্যন্ত একটা ডাবল রুম। আপনার একটা ছবিওয়ালা পরিচয়পত্র দেখাবেন?",
        "everyday|5:1|5|l3": "এই নিন আমার আধার কার্ড। ভাড়ার মধ্যে কি ব্রেকফাস্ট ধরা আছে?",
        "everyday|5:1|5|l4": "হ্যাঁ, আছে। রেস্তোরাঁয় সকাল সাতটা থেকে দশটা পর্যন্ত ব্রেকফাস্ট দেওয়া হয়।",
        "everyday|5:1|5|l5": "বাহ্। লিফট থেকে একটু দূরে কোনো ঘর পাওয়া যাবে? আমার ঘুম খুব পাতলা।",
        "everyday|5:1|5|l6": "নিশ্চয়ই। আপনাকে ৩১২ নম্বর ঘরটা দিচ্ছি, করিডরের শান্ত দিকটায়।",
        "everyday|5:1|5|l7": "ধন্যবাদ। আর শুক্রবার চেক-আউট ক'টায়?",
        "everyday|5:1|5|l8": "চেক-আউট এগারোটায়, তবে একটু বাড়তি সময় লাগলে আমাদের জানাবেন।",
        "everyday|5:1|5|l9": "এটা খুব কাজের কথা। অনেক ধন্যবাদ।",
