        "everyday|6:1|3|p0": "দিল্লির কাছে ঘন কুয়াশার জন্য চার ঘণ্টা দেরি হচ্ছে।",
        "everyday|6:1|3|p1": "দু'দিনের বেশি আগে বাতিল করলে বাতিলের চার্জ সামান্য।",
        "everyday|6:1|3|p2": "বাসটা বাতিল হয়ে গেল, তাই টাকা ফেরত চাইতে অনুসন্ধান কাউন্টারে গেলাম।",
        "everyday|6:1|3|p3": "ঘোষণাটা শুনতে পেলে? আমাদের মালপত্র নিয়ে পাঁচ নম্বর প্ল্যাটফর্মে যেতে হবে।",
        "everyday|6:1|3|p4": "সময়সূচি অনুযায়ী মাইসুরুর শেষ বাস ছাড়ে রাত দশটায়।",
        "everyday|6:1|4|title": "ঠিক সময়মতো",
        "everyday|6:1|4|text": "আশা বোনের বিয়েতে যোগ দিতে হুব্বল্লি থেকে পুনে যাচ্ছিল। দু'মাস আগেই সে রিজার্ভেশন করে রেখেছিল, আর এস-ফোর কামরায় তার একটা নিচের বার্থ ছিল। স্টেশনে ঘোষণা হল যে ট্রেন তিন ঘণ্টা দেরিতে আসবে। আশা ফোনে বাসের সময়সূচি দেখে এমন একটা বাস খুঁজে পেল যেটা আরও আগে পুনে পৌঁছবে। সে অনলাইনে ট্রেনের টিকিট বাতিল করল, আর দু'দিনের মধ্যে টাকা তার অ্যাকাউন্টে ফেরত এল। অল্প পয়সার বিনিময়ে একজন কুলি তার ভারী ব্যাগগুলো বাসস্ট্যান্ড পর্যন্ত বয়ে দিল। মেহেন্দির ঠিক সময়ে সে পুনে পৌঁছে গেল।",
