        "everyday|6:1|5|scenario": "মাইসুরু রেলস্টেশনে কবিতা জানতে পারে যে তার বেঙ্গালুরুর ট্রেন বাতিল হয়েছে, আর সে অনুসন্ধান কাউন্টারে সুরেশের কাছে সাহায্য চায়।",
        "everyday|6:1|5|l0": "শুনছেন, এইমাত্র ঘোষণা শুনলাম যে চামুণ্ডী এক্সপ্রেস বাতিল হয়েছে। এটা কি ঠিক?",
        "everyday|6:1|5|l1": "হ্যাঁ ম্যাডাম, দুঃখিত। মান্ড্যার কাছে লাইনে একটা সমস্যা হয়েছে।",
        "everyday|6:1|5|l2": "সর্বনাশ। দুটোয় বেঙ্গালুরুতে আমার একটা জরুরি মিটিং আছে। এখন আমি কী করতে পারি?",
        "everyday|6:1|5|l3": "তিন নম্বর প্ল্যাটফর্ম থেকে সোয়া এগারোটায় একটা এক্সপ্রেস আছে। ওটা সাধারণত দেড়টার মধ্যে পৌঁছে যায়।",
        "everyday|6:1|5|l4": "ওতে কি কোনো সিট খালি আছে?",
        "everyday|6:1|5|l5": "দুঃখিত, শুধু জেনারেল কামরায়। রিজার্ভড সিট সব ওয়েটিং লিস্টে।",
        "everyday|6:1|5|l6": "জেনারেল কামরাতেই চলবে। আর আমার বাতিল টিকিটের কী হবে?",
        "everyday|6:1|5|l7": "রেলই যেহেতু ট্রেন বাতিল করেছে, আপনি এক সপ্তাহের মধ্যে পুরো টাকা ফেরত পাবেন।",
        "everyday|6:1|5|l8": "টাকা ফেরতের জন্য কি কোনো ফর্ম ভরতে হবে?",
        "everyday|6:1|5|l9": "না ম্যাডাম। আপনি অনলাইনে বুক করেছেন, তাই এটা নিজে থেকেই হয়ে যাবে। আপনার যাত্রা শুভ হোক।",
        "everyday|6:1|5|q0": "চামুণ্ডী এক্সপ্রেস কেন বাতিল হয়েছিল?",
