        "services|1:1|1|p1": "দশ বছরের বাচ্চার জন্য ঠিক মাত্রাটা কত, একটু বলবেন?",
        "services|1:1|1|p2": "কেমিস্ট বললেন প্রতিবার খাওয়ার পরে একটা করে ট্যাবলেট খেতে হবে।",
