        "services|1:1|3|p0": "দিনে দু'বার পোড়া জায়গায় এই মলমটা আলতো করে লাগান।",
        "services|1:1|3|p1": "আমার পেনিসিলিনে অ্যালার্জি আছে, তাই দয়া করে অন্য কিছু দিন।",
        "services|1:1|3|p2": "নতুন স্ট্রিপ খোলার আগে সবসময় মেয়াদ শেষের তারিখ দেখে নিন।",
        "services|1:1|3|p3": "ভালো বোধ করলেও অ্যান্টিবায়োটিকের পুরো কোর্সটা শেষ করুন।",
        "services|1:1|3|p4": "এই ব্যথার ওষুধে ঘুম-ঘুম ভাব আসতে পারে, তাই খাওয়ার পরে গাড়ি চালাবেন না।",
        "services|1:1|4|title": "গভীর রাতে ওষুধের দোকানে",
        "services|1:1|4|text": "মাইসুরুতে এক রাতে দশটার সময় মীরার ছোট ভাই রোহন খুব জ্বর নিয়ে ঘুম থেকে উঠল। তাদের পারিবারিক ডাক্তার শহরের বাইরে ছিলেন, তাই মীরা পরামর্শের জন্য তাঁকে ফোন করল। ডাক্তার বললেন সকাল পর্যন্ত জ্বরের একটা সিরাপই যথেষ্ট। মীরা বাসস্ট্যান্ডের কাছে সারা রাত খোলা থাকে এমন একটা ওষুধের দোকান খুঁজে পেল। সে কেমিস্টকে জানাল যে রোহনের বয়স আট বছর, আর একটা অ্যান্টিবায়োটিকে তার অ্যালার্জি আছে। কেমিস্ট মেয়াদ শেষের তারিখ দেখে নিলেন, বাক্সের ওপর ওষুধের মাত্রা লিখে দিলেন, আর সাবধান করে দিলেন যে সিরাপটা খেলে রোহনের ঘুম-ঘুম ভাব আসতে পারে। সকালের মধ্যে রোহনের জ্বর নেমে গেল, আর সে দোসা খেতে চাইছিল।",
        "services|1:1|4|q0": "মীরা রাতে ওষুধের দোকানে গিয়েছিল কেন?",
