        "services|1:1|5|l0": "শুভ সন্ধ্যা। বলুন, কী সাহায্য করতে পারি?",
        "services|1:1|5|l1": "নমস্কার। কাল থেকে আমার নাক বন্ধ আর গলা ব্যথা। কিছু একটা দেবেন?",
        "services|1:1|5|l2": "জ্বর আছে, বা কোনো ওষুধে অ্যালার্জি?",
        "services|1:1|5|l3": "জ্বর নেই, আর যতদূর জানি কোনো অ্যালার্জিও নেই। খুব কড়া কিছু না খেলেই ভালো।",
        "services|1:1|5|l4": "তাহলে সর্দির জন্য এই ট্যাবলেটগুলো খান, সকালে একটা আর রাতে একটা, খাওয়ার পরে।",
        "services|1:1|5|l5": "এর কি কোনো পার্শ্বপ্রতিক্রিয়া আছে যা আমার জানা দরকার?",
        "services|1:1|5|l6": "একটু ঘুম-ঘুম ভাব আসতে পারে, তাই রাতের ডোজের পরে গাড়ি চালাবেন না।",
        "services|1:1|5|l7": "বুঝলাম। আর গলার জন্যও কিছু আছে?",
        "services|1:1|5|l8": "এই সিরাপটায় কাজ হবে: দু'চামচ করে, দিনে তিনবার। তিন দিনে ভালো না হলে দয়া করে ডাক্তার দেখাবেন।",
        "services|1:1|5|l9": "খুব উপকার হল, ধন্যবাদ। ইউপিআই দিয়ে টাকা দিতে পারি?",
        "services|1:1|5|q0": "কিরণকে কতবার ট্যাবলেট খেতে হবে?",
        "services|1:1|5|q0o0": "দিনে দু'বার, খাওয়ার পরে",
