        "services|2:1|0|w5": "ল্যান্ডমার্ক",
        "services|2:1|1|p0": "আমি হুব্বল্লি বাসস্ট্যান্ডের কাছে একটা পথ দুর্ঘটনার খবর দিতে চাই।",
        "services|2:1|1|p1": "দয়া করে তাড়াতাড়ি একটা অ্যাম্বুলেন্স পাঠান; একজন লোক রাস্তায় পড়ে আছেন।",
        "services|2:1|1|p2": "জরুরি অবস্থায় ১১২ হেল্পলাইনে ফোন করুন আর ধীরে ধীরে স্পষ্ট করে কথা বলুন।",
        "services|2:1|1|p3": "দমকল আসছে, তাই দয়া করে এখনই বিল্ডিং থেকে বেরিয়ে যান।",
        "services|2:1|1|p4": "সবচেয়ে কাছের ল্যান্ডমার্ক হল পেট্রল পাম্পের উল্টোদিকের বড় মন্দিরটা।",
        "services|2:1|2|w0": "আহত",
        "services|2:1|2|w1": "অজ্ঞান",
        "services|2:1|2|w2": "রক্তপাত",
        "services|2:1|2|w3": "প্রাথমিক চিকিৎসা",
        "services|2:1|2|w4": "চুরি",
        "services|2:1|2|w5": "আতঙ্ক",
        "services|2:1|3|p0": "দু'জন আহত হয়েছেন, আর তাঁদের একজন অজ্ঞান।",
        "services|2:1|3|p1": "রক্তপাত বন্ধ করতে ক্ষতের ওপর একটা পরিষ্কার কাপড় চেপে ধরুন।",
        "services|2:1|3|p2": "আপনি কি প্রাথমিক চিকিৎসা জানেন, নাকি আমরা অ্যাম্বুলেন্সের জন্য অপেক্ষা করব?",
        "services|2:1|3|p3": "স্টেশনে আমার ব্যাগ চুরি হয়ে গেছে, আর চুরির রিপোর্ট করতে হবে।",
        "services|2:1|3|p4": "আতঙ্কিত হবেন না; একটা গভীর শ্বাস নিন আর আমাকে আপনার ঠিকানা বলুন।",
        "services|2:1|4|title": "হাইওয়েতে সাহায্য",
        "services|2:1|4|text": "রবি ম্যাঙ্গালুরু থেকে উডুপি গাড়ি চালিয়ে যাচ্ছিল, তখন সে দেখল হাইওয়ের ধারে একটা বাইক পড়ে আছে। পাশে একজন যুবক বসে ছিল, আর তার হাত থেকে খুব রক্ত পড়ছিল। রবি গাড়ি থামাল আর নিজেকে বলল আতঙ্কিত না হতে। সে ১০৮-এ ফোন করে বলল, 'আমি একটা দুর্ঘটনার খবর দিতে চাই; একজন আহত।' অপারেটর সঠিক জায়গাটা জানতে চাইলেন, তাই রবি সবচেয়ে কাছের ল্যান্ডমার্ক, সুরতকল লাইটহাউসের কথা বলল। অপেক্ষা করতে করতে রবি ক্ষতের ওপর একটা পরিষ্কার তোয়ালে চেপে ধরে প্রাথমিক চিকিৎসা করল। পনেরো মিনিটে অ্যাম্বুলেন্স এসে পৌঁছল, আর পরে যুবকটি শান্ত থাকার জন্য রবিকে ধন্যবাদ জানাল।",
        "services|2:1|4|q0": "রবি বাইকটা কোথায় দেখেছিল?",
