        "services|2:1|4|q2o3": "তিরিশ মিনিট",
        "services|2:1|5|title": "১১২-এ ফোন",
        "services|2:1|5|scenario": "পুনেতে নন্দিনী দেখে তার গলির একটা বাড়ি থেকে ধোঁয়া বেরোচ্ছে, আর সে ১১২ জরুরি হেল্পলাইনে ফোন করে। সুরেশ ফোন ধরেন।",
        "services|2:1|5|l0": "১১২ জরুরি হেল্পলাইন। বলুন, কী জরুরি অবস্থা?",
        "services|2:1|5|l1": "আমাদের রাস্তার একটা বাড়িতে আগুন লেগেছে। দোতলার জানলা দিয়ে ঘন ধোঁয়া বেরোতে দেখছি।",
        "services|2:1|5|l2": "দয়া করে শান্ত থাকুন, ম্যাডাম। বাড়ির ভেতরে কি এখনও কেউ আছেন?",
        "services|2:1|5|l3": "ঠিক জানি না। ওখানে এক বয়স্ক দম্পতি থাকেন, আর ওঁদের বাইরে দেখতে পাচ্ছি না।",
        "services|2:1|5|l4": "আমি এখনই দমকল আর একটা অ্যাম্বুলেন্স পাঠাচ্ছি। ঠিক ঠিকানাটা কী?",
        "services|2:1|5|l5": "চোদ্দো নম্বর বাড়ি, শান্তি নগর, কোথরুড। ল্যান্ডমার্ক হল মোড়ের নীল জলের ট্যাঙ্কটা।",
        "services|2:1|5|l6": "ধন্যবাদ। দয়া করে ভেতরে যাবেন না, আর অন্যদের ধোঁয়া থেকে দূরে রাখুন।",
        "services|2:1|5|l7": "ঠিক আছে। ও, একজন প্রতিবেশী বলছেন ওঁরা মন্দিরে গেছেন, তাই বাড়িটা খালি।",
        "services|2:1|5|l8": "এটা ভালো খবর। দমকল মোটামুটি দশ মিনিটের মধ্যে আপনার কাছে পৌঁছে যাবে। দয়া করে লাইনে থাকুন।",
        "services|2:1|5|l9": "অনেক ধন্যবাদ। সাইরেনের আওয়াজ এর মধ্যেই শুনতে পাচ্ছি।",
        "services|2:1|5|q0": "নন্দিনী ১১২-এ ফোন করেছিল কেন?",
        "services|2:1|5|q0o0": "সে একটা বাড়ি থেকে ধোঁয়া বেরোতে দেখেছিল",
