        "services|3:1|0|w5": "ফিউজ",
        "services|3:1|1|p0": "রান্নাঘরের কল থেকে সারা রাত টপটপ করে জল পড়ছে; আজ একজন কলের মিস্ত্রি পাঠাতে পারবেন?",
        "services|3:1|1|p1": "বাথরুমের বেসিনের নিচে লিক আছে, আর মেঝেটা সবসময় ভিজে থাকে।",
        "services|3:1|1|p2": "যতবার গিজার চালাই, ততবার ফিউজ উড়ে যায়।",
        "services|3:1|1|p3": "ইলেকট্রিক মিস্ত্রি বলছেন এই ফ্ল্যাটের পুরোনো ওয়্যারিং নিরাপদ নয়।",
        "services|3:1|1|p4": "কোনো তারে হাত দেওয়ার আগে দয়া করে মেন সুইচটা বন্ধ করে দিন।",
