        "services|3:1|3|p0": "আমাদের ওয়াশিং মেশিনে একটা ত্রুটি আছে; প্রতিবার কাচার মাঝপথে থেমে যায়।",
        "services|3:1|3|p1": "টেকনিশিয়ান কি কাল সকালে, আমার কাজে বেরোনোর আগে আসতে পারবেন?",
        "services|3:1|3|p2": "কাজ শুরুর আগে মোট আনুমানিক খরচটা বলতে পারবেন?",
        "services|3:1|3|p3": "যন্ত্রাংশটা বেঙ্গালুরু থেকে আসতে তিন দিন লাগবে।",
        "services|3:1|3|p4": "যেকোনো বড় ঘরোয়া যন্ত্রের জন্য প্রতিবার আসার সার্ভিস চার্জ তিনশো টাকা।",
        "services|3:1|4|title": "যে ফ্রিজ ঠান্ডা করা বন্ধ করে দিল",
        "services|3:1|4|text": "মে মাসের এক গরম সপ্তাহে কলবুর্গিতে কুলকার্নি পরিবারের ফ্রিজ হঠাৎ ঠান্ডা করা বন্ধ করে দিল। সুনীতা কোম্পানির সার্ভিস সেন্টারে ফোন করে ত্রুটিটা পরিষ্কার করে বুঝিয়ে বলল: আলো জ্বলছে, কিন্তু ভেতরটা গরম। পরদিন বিকেলে একজন টেকনিশিয়ান এসে যন্ত্রটা ভালো করে দেখলেন। তিনি বললেন কুলিং সিস্টেমের একটা যন্ত্রাংশ খারাপ হয়ে গেছে, ওটা বদলাতে হবে। কাজ শুরুর আগে সুনীতা ভদ্রভাবে আনুমানিক খরচ জানতে চাইল, আর তিনি বললেন সার্ভিস চার্জ ধরে মোট মোটামুটি দু'হাজার টাকা পড়বে। দু'দিন পরে হুব্বল্লি থেকে যন্ত্রাংশটা এল, আর টেকনিশিয়ান এক ঘণ্টার মধ্যে ফ্রিজ সারিয়ে দিলেন। সেদিন সন্ধ্যায় ফ্রিজ আবার ঠান্ডা হল, আর অবশেষে পরিবারটা দুধ আর দই রাখতে পারল।",
        "services|3:1|4|q0": "ফ্রিজটার কী হয়েছিল?",
