        "services|3:1|5|title": "ইলেকট্রিক মিস্ত্রি ডাকা",
        "services|3:1|5|scenario": "ফারহানের ফ্ল্যাটে বারবার ফিউজ উড়ে যাচ্ছে, তাই সে আশাকে ফোন করে, যিনি মাইসুরুতে বাড়ি সারাইয়ের একটা সার্ভিস চালান।",
        "services|3:1|5|l0": "সুপ্রভাত, কুইকফিক্স হোম সার্ভিসেস। আমি আশা বলছি। কী সাহায্য করতে পারি?",
        "services|3:1|5|l1": "নমস্কার, ইলেকট্রিকের একটা সমস্যার জন্য ফোন করছি। আমার ফ্ল্যাটে বারবার ফিউজ উড়ে যাচ্ছে, বেশিরভাগ সন্ধেবেলায়।",
        "services|3:1|5|l2": "বুঝলাম। কোনো একটা নির্দিষ্ট যন্ত্র চালালেই কি এটা হয়?",
        "services|3:1|5|l3": "মনে হয় হ্যাঁ। গিজার আর ইস্ত্রি একসঙ্গে চললে সাধারণত এটা হয়।",
        "services|3:1|5|l4": "ওয়্যারিংয়ে কোনো ত্রুটি থাকতে পারে। দেখার জন্য আমি একজন ইলেকট্রিক মিস্ত্রি পাঠাতে পারি। কখন আপনার সুবিধা হবে?",
        "services|3:1|5|l5": "আজই কাউকে পাঠাতে পারবেন? আমি ছ'টা পর্যন্ত বাড়ি থেকে কাজ করছি।",
        "services|3:1|5|l6": "আমাদের ইলেকট্রিক মিস্ত্রি মহেশ চারটেয় আসতে পারবেন। একবার আসার সার্ভিস চার্জ আড়াইশো টাকা।",
        "services|3:1|5|l7": "চলবে। সারাই শুরু করার আগে উনি কি আনুমানিক খরচ বলে দেবেন?",
        "services|3:1|5|l8": "হ্যাঁ, উনি সবসময় আগে খরচটা বুঝিয়ে বলেন। দয়া করে হোয়াটসঅ্যাপে আপনার ঠিকানাটা পাঠিয়ে দিন।",
        "services|3:1|5|l9": "দারুণ, এখনই পাঠাচ্ছি। ধন্যবাদ।",
