        "services|4:1|1|p0": "গত সপ্তাহে এখান থেকে কেনা একটা মিক্সি নিয়ে আমি অভিযোগ জানাতে চাই।",
        "services|4:1|1|p1": "মোটরটা ত্রুটিপূর্ণ, তাই আমি এটা বদলে নিতে চাই, নয়তো পুরো টাকা ফেরত।",
        "services|4:1|1|p2": "এই নিন রসিদ, আর বাক্সে এখনও সব অংশ আছে।",
        "services|4:1|1|p3": "এটা এখনও ওয়ারেন্টির মধ্যে আছে, তাই সারাই বিনা পয়সায় হওয়া উচিত।",
        "services|4:1|1|p4": "দুঃখিত, কিন্তু ভাউচার যথেষ্ট নয়; আমি সত্যিই টাকা ফেরত চাই।",
        "services|4:1|2|w0": "কাস্টমার কেয়ার",
        "services|4:1|2|w1": "সুপারভাইজার",
        "services|4:1|2|w2": "ওপরমহলে জানানো",
        "services|4:1|2|w3": "ক্ষতিপূরণ",
        "services|4:1|2|w4": "ডেলিভারি",
        "services|4:1|2|w5": "অসুবিধা",
        "services|4:1|3|p0": "আমি তিনবার কাস্টমার কেয়ারে ফোন করেছি, অথচ কেউ সমস্যাটার সমাধান করেনি।",
        "services|4:1|3|p1": "এ বিষয়ে আমি কি দয়া করে আপনার সুপারভাইজারের সঙ্গে কথা বলতে পারি?",
        "services|4:1|3|p2": "শুক্রবারের মধ্যে ঠিক না হলে আমাকে অভিযোগটা ওপরমহলে জানাতে হবে।",
        "services|4:1|3|p3": "ডেলিভারি দশ দিন দেরিতে এসেছিল, আর পার্সেলটা ভাঙাচোরা ছিল।",
        "services|4:1|3|p4": "অসুবিধার জন্য আমরা দুঃখিত, আর ক্ষতিপূরণ হিসেবে দু'শো টাকা যোগ করে দেব।",
        "services|4:1|4|title": "ভদ্র কিন্তু দৃঢ়",
        "services|4:1|4|text": "ইমরান বেলগাভিতে তার মায়ের জন্য অনলাইনে একটা ইলেকট্রিক কেটলি অর্ডার করেছিল, কিন্তু ডেলিভারি এল এক সপ্তাহ দেরিতে। মা সেটা চালাতেই কেটলি থেকে পোড়া গন্ধ বেরোল আর সেটা বন্ধ হয়ে গেল। ইমরান কাস্টমার কেয়ারে ফোন করে অর্ডার নম্বর দিল আর বুঝিয়ে বলল যে জিনিসটা ত্রুটিপূর্ণ। প্রথম এজেন্ট শুধু একটা ভাউচার দিতে চাইলেন, তাই ইমরান ভদ্রভাবে সুপারভাইজারের সঙ্গে কথা বলতে চাইল। সে শান্ত কিন্তু দৃঢ় থেকে বলল, 'দুঃখিত, ভাউচার যথেষ্ট নয়; কেটলিটা ওয়ারেন্টির মধ্যে আছে, আর আমার কাছে রসিদ আছে।' সুপারভাইজার অসুবিধার জন্য দুঃখপ্রকাশ করলেন আর দু'দিনের মধ্যে বদলি কেটলি পাঠাতে রাজি হলেন। দেরিতে ডেলিভারির ক্ষতিপূরণ হিসেবে তিনি তার অ্যাকাউন্টে একশো টাকাও যোগ করে দিলেন।",
        "services|4:1|4|q0": "কেটলিটার কী সমস্যা ছিল?",
        "services|4:1|4|q0o0": "পোড়া গন্ধ বেরিয়ে সেটা বন্ধ হয়ে গিয়েছিল",
