        "services|4:1|4|q1o0": "প্রথম এজেন্ট শুধু ভাউচার দিতে চেয়েছিলেন",
        "services|4:1|4|q1o1": "এজেন্ট তার সঙ্গে অভদ্র ব্যবহার করেছিলেন",
        "services|4:1|4|q1o2": "সে কোম্পানিতে চাকরি চাইছিল",
        "services|4:1|4|q1o3": "ফোনটা বারবার কেটে যাচ্ছিল",
        "services|4:1|4|q2": "সুপারভাইজার কী করতে রাজি হলেন?",
        "services|4:1|4|q2o0": "দু'দিনের মধ্যে বদলি কেটলি পাঠাতে",
        "services|4:1|4|q2o1": "সঙ্গে সঙ্গে পুরো টাকা ফেরত দিতে",
        "services|4:1|4|q2o2": "পরের মাসে কেটলি সারাতে",
        "services|4:1|4|q2o3": "তার বাড়িতে টেকনিশিয়ান পাঠাতে",
        "services|4:1|5|title": "কাস্টমার কেয়ারে ফোন",
        "services|4:1|5|scenario": "দীপা ভুল কুর্তা পেয়েছে, তাই সে একটা অনলাইন দোকানের কাস্টমার কেয়ার লাইনে ফোন করে। প্রকাশ ফোন ধরেন।",
        "services|4:1|5|l0": "শপকার্ট কাস্টমার কেয়ারে ফোন করার জন্য ধন্যবাদ। আমি প্রকাশ বলছি। কীভাবে সাহায্য করতে পারি?",
        "services|4:1|5|l1": "নমস্কার, প্রকাশ। আমি ৪৫৮২ নম্বর অর্ডারের ব্যাপারে ফোন করছি। কাল আমি ভুল জিনিস পেয়েছি।",
        "services|4:1|5|l2": "শুনে খারাপ লাগল। আপনি কী অর্ডার করেছিলেন আর কী পেয়েছেন, একটু বলবেন?",
        "services|4:1|5|l3": "আমি মিডিয়াম মাপের একটা নীল সুতির কুর্তা অর্ডার করেছিলাম, কিন্তু পেয়েছি এক্সট্রা লার্জ মাপের একটা লাল কুর্তা।",
        "services|4:1|5|l4": "অসুবিধার জন্য দুঃখিত। আপনি বদলি জিনিস চান, নাকি টাকা ফেরত?",
        "services|4:1|5|l5": "টাকা ফেরত পেলেই ভালো হয়। এই রবিবার একটা বিয়ের জন্য ওটা দরকার ছিল, আর নতুনটা সময়মতো আসবে না।",
        "services|4:1|5|l6": "বুঝেছি। আমাদের ডেলিভারি পার্টনার কাল দশটা থেকে দুটোর মধ্যে পার্সেলটা নিয়ে যাবেন।",
        "services|4:1|5|l7": "আর টাকা ফেরত আমার অ্যাকাউন্টে পৌঁছতে কত দিন লাগবে?",
        "services|4:1|5|l8": "পার্সেল নিয়ে যাওয়ার পর পাঁচ কাজের দিনের মধ্যে টাকা আপনার অ্যাকাউন্টে পৌঁছে যাবে।",
        "services|4:1|5|l9": "ঠিক আছে। অভিযোগের নম্বরটাও কি আমাকে এসএমএস করে পাঠাবেন?",
