        "services|5:1|1|p0": "আয়ের সার্টিফিকেটের আবেদনপত্র কোথায় পাব?",
        "services|5:1|1|p1": "দয়া করে আসল নথিগুলোর সঙ্গে প্রত্যেকটার একটা করে ফটোকপি নিয়ে আসবেন।",
        "services|5:1|1|p2": "আপনি দ্বিতীয় পাতায় সই করতে ভুলে গেছেন।",
