        "services|5:1|2|w5": "প্রাপ্তিস্বীকার",
        "services|5:1|3|p0": "দয়া করে একটা টোকেন নিন আর আপনার নম্বর ডাকা পর্যন্ত অপেক্ষা করুন।",
        "services|5:1|3|p1": "শুনছেন, আধার আপডেটের জন্য এটাই কি ঠিক লাইন?",
        "services|5:1|3|p2": "আধিকারিক বললেন আমার আঙুলের ছাপ আবার স্ক্যান করতে হবে।",
        "services|5:1|3|p3": "পাসপোর্টের পুলিশ যাচাইয়ে সাধারণত মোটামুটি দু'সপ্তাহ লাগে।",
        "services|5:1|3|p4": "এই প্রাপ্তিস্বীকারটা যত্ন করে রাখুন; আবেদনের খবর জানতে এটা লাগবে।",
        "services|5:1|4|title": "আধার কেন্দ্রে একটা সকাল",
        "services|5:1|4|text": "কাজের জন্য লক্ষ্মী শিবমোগ্গা থেকে পুনেতে চলে এসেছিল, তাই তার আধার কার্ডের ঠিকানা বদলানোর দরকার ছিল। সে সকাল আটটায় আধার কেন্দ্রে পৌঁছল, কিন্তু তখনই লম্বা লাইন পড়ে গেছে। একজন গার্ড তাকে বিয়াল্লিশ নম্বরের একটা টোকেন আর পূরণ করার জন্য একটা আবেদনপত্র দিলেন। তার পালা এলে আধিকারিক তার নথিগুলো দেখলেন, আর ঠিকানার প্রমাণ হিসেবে ইলেকট্রিক বিলের একটা ফটোকপি চাইলেন। ভাগ্যিস লক্ষ্মী দুটো কপি এনেছিল, আর প্রতিটা পাতায় আগেই সই করে রেখেছিল। তারপর আধিকারিক যাচাইয়ের জন্য তার আঙুলের ছাপ স্ক্যান করলেন আর একটা প্রাপ্তিস্বীকার স্লিপ ছাপিয়ে দিলেন। তিনি বললেন দশ দিনের মধ্যে নতুন ঠিকানা আপডেট হয়ে যাবে, আর দুপুরের আগেই লক্ষ্মী নিশ্চিন্ত মনে অফিস থেকে বেরিয়ে এল।",
        "services|5:1|4|q0": "লক্ষ্মী আধার কেন্দ্রে গিয়েছিল কেন?",
