        "services|5:1|5|title": "পাসপোর্ট অফিসে",
        "services|5:1|5|scenario": "বিক্রম হুব্বল্লির পাসপোর্ট সেবা কেন্দ্রে এসেছে, যেখানে কাউন্টারের আধিকারিক শালিনী তার নথিপত্র দেখছেন।",
        "services|5:1|5|l0": "সুপ্রভাত। আপনার টোকেন স্লিপ আর অ্যাপয়েন্টমেন্টের প্রিন্টআউটটা দেবেন?",
        "services|5:1|5|l1": "সুপ্রভাত, ম্যাডাম। এই যে। এটা আমার প্রথম পাসপোর্টের আবেদন।",
        "services|5:1|5|l2": "ধন্যবাদ। আপনার আধার কার্ড আর ঠিকানার আরও একটা প্রমাণ লাগবে। কী এনেছেন?",
        "services|5:1|5|l3": "আধার কার্ড এনেছি, জন্মতারিখের জন্য দশম শ্রেণির সার্টিফিকেট, আর সাম্প্রতিক একটা গ্যাসের বিল।",
        "services|5:1|5|l4": "গ্যাসের বিলটা আপনার বাবার নামে। আপনার নিজের নামে কিছু আছে?",
        "services|5:1|5|l5": "না, নেই। তবে ঠিকানা লেখা আমার ব্যাংকের পাসবইয়ের একটা ফটোকপি এনেছি। ওতে চলবে?",
        "services|5:1|5|l6": "হ্যাঁ, চলবে। এখানে সই করুন, তারপর ছবি আর আঙুলের ছাপের জন্য বি কাউন্টারে যান।",
        "services|5:1|5|l7": "নিশ্চয়ই। এরপর পুলিশ যাচাইয়ে কত দিন লাগবে?",
        "services|5:1|5|l8": "সাধারণত দুই থেকে তিন সপ্তাহ। পুলিশ আপনার কাছে আসার জন্য তৈরি হলে আপনি একটা এসএমএস পাবেন।",
        "services|5:1|5|l9": "আপনার সাহায্যের জন্য অনেক ধন্যবাদ, ম্যাডাম।",
        "services|5:1|5|q0": "বিক্রম গ্যাসের বিলটা কেন কাজে লাগাতে পারল না?",
