        "services|6:1|1|p1": "ভাড়াটা কি একটু কমানো যাবে, নাকি এটাই শেষ কথা?",
        "services|6:1|1|p2": "ব্রোকার তাঁর ফি হিসেবে এক মাসের ভাড়া নেন।",
        "services|6:1|1|p3": "আমরা মেট্রো স্টেশনের কাছে পুরো আসবাবসহ একটা ফ্ল্যাট খুঁজছি।",
        "services|6:1|1|p4": "ভাড়াটে হিসেবে প্রতিটা পেমেন্টের রসিদ পাওয়া আপনার অধিকার।",
