        "services|6:1|3|p0": "সই করার আগে দয়া করে ভাড়ার চুক্তিটা মন দিয়ে পড়ে নিন।",
        "services|6:1|3|p1": "মাসিক রক্ষণাবেক্ষণের খরচ কি ভাড়ার মধ্যে ধরা আছে, নাকি আলাদা?",
        "services|6:1|3|p2": "আমাদের প্রতিবেশীরা আন্তরিক, কিন্তু অনেক রাত পর্যন্ত জোরে গান চালান।",
        "services|6:1|3|p3": "নোটিশের মেয়াদ দু'মাস, তাই জুলাইয়ের মধ্যে বাড়িওয়ালাকে জানাতে হবে।",
        "services|6:1|3|p4": "ফ্ল্যাট খালি করার সময় আমরা ইলেকট্রিক মিটারের রিডিংটা লিখে রাখব।",
        "services|6:1|4|title": "মাইসুরুতে নতুন ফ্ল্যাট",
        "services|6:1|4|text": "মাইসুরুতে চাকরি পাওয়ার পর অনিতা কুভেম্পুনগরের কাছে একটা ছোট ফ্ল্যাট খুঁজতে শুরু করল। একজন ব্রোকার তাকে চারটে জায়গা দেখালেন, আর তিনতলার আসবাবসহ এক কামরার একটা ফ্ল্যাট তার পছন্দ হল। বাড়িওয়ালা মিস্টার গৌড়া মাসে বারো হাজার টাকা ভাড়া আর ষাট হাজার টাকা ডিপোজিট চাইলেন। অনিতা ভদ্রভাবে জানতে চাইল ডিপোজিট একটু কম করা যায় কি না, আর শেষমেশ তাঁরা পঞ্চাশ হাজারে রাজি হলেন। ভাড়ার চুক্তিতে সই করার আগে সে নোটিশের মেয়াদ দেখে নিল, আর জিজ্ঞেস করল মাসিক রক্ষণাবেক্ষণের খরচ কে দেবে। সে ইলেকট্রিক মিটারের একটা ছবিও তুলে রাখল, যাতে পরে বিল নিয়ে কোনো গোলমাল না হয়। প্রথম সন্ধ্যায় এক আন্তরিক প্রতিবেশী তার জন্য এক প্লেট গরম বিসি বেলে বাথ নিয়ে এলেন।",
        "services|6:1|4|q0": "শেষমেশ অনিতা কত টাকা ডিপোজিট দিতে রাজি হল?",
