        "services|6:1|5|title": "বাড়িওয়ালিকে ফোন",
        "services|6:1|5|scenario": "পুনের ভাড়াটে রাহুল ফ্ল্যাটের একটা সমস্যা আর বাড়ি ছাড়ার ব্যাপারে তার বাড়িওয়ালি মিসেস যোশীকে ফোন করে।",
        "services|6:1|5|l0": "নমস্কার, মিসেস যোশী। আমি থ্রি-বি ফ্ল্যাটের রাহুল বলছি। এক মিনিট সময় হবে?",
        "services|6:1|5|l1": "হ্যাঁ রাহুল, বলো। সব ঠিক আছে তো?",
        "services|6:1|5|l2": "ঠিক নয়। সোমবার থেকে বাথরুমের সিলিং দিয়ে জল চুঁইয়ে পড়ছে, আর দেওয়ালটা স্যাঁতসেঁতে হয়ে যাচ্ছে।",
        "services|6:1|5|l3": "ইশ। নিশ্চয়ই ছাদের ট্যাঙ্কটা থেকে। আমি কাল সকালে আমাদের কলের মিস্ত্রি সুনীলকে পাঠাচ্ছি।",
        "services|6:1|5|l4": "ধন্যবাদ। সারাইয়ের খরচ কি রক্ষণাবেক্ষণের টাকা থেকে যাবে, নাকি আমাকে দিতে হবে?",
        "services|6:1|5|l5": "চিন্তা কোরো না, বাড়িওয়ালি হিসেবে ওটা আমার দায়িত্ব। তুমি শুধু বাল্বের মতো ছোটখাটো জিনিসের খরচ দেবে।",
        "services|6:1|5|l6": "আপনি খুব ভালো। আরও একটা কথা: আমার কোম্পানি মার্চে আমাকে নাসিকে বদলি করছে।",
        "services|6:1|5|l7": "বুঝলাম। চুক্তি অনুযায়ী নোটিশের মেয়াদ দু'মাস, তাই জানুয়ারির মধ্যে আমাকে লিখিত নোটিশ দিও।",
        "services|6:1|5|l8": "এই সপ্তাহেই আপনাকে নোটিশটা ইমেল করে দেব। আর ফ্ল্যাট খালি করলে ডিপোজিটটা ফেরত পাব, তাই তো?",
        "services|6:1|5|l9": "হ্যাঁ। ফ্ল্যাট আর শেষ ইলেকট্রিক বিল দেখে নিয়ে এক সপ্তাহের মধ্যে ট্রান্সফার করে দেব।",
        "services|6:1|5|q0": "রাহুল কোন সমস্যার কথা জানায়?",
        "services|6:1|5|q0o0": "বাথরুমের সিলিং দিয়ে জল চুঁইয়ে পড়ছে",
