        "workplace|1:1|1|p0": "আমার এখনকার ভূমিকায় আমি গোটা কোম্পানির বেতনের হিসেব দেখি।",
        "workplace|1:1|1|p1": "আপনি কোন বিভাগে কাজ করেন, আর কার কাছে রিপোর্ট করেন?",
        "workplace|1:1|1|p2": "খাতায়-কলমে আমার পদ সিনিয়র অ্যানালিস্ট, কিন্তু আমার কাজ প্রতি সপ্তাহে বদলায়।",
        "workplace|1:1|1|p3": "আমি ছ'জনের একটা দলের তত্ত্বাবধান করি আর ক্লায়েন্টদের বেশিরভাগ ফোন সামলাই।",
        "workplace|1:1|1|p4": "সাধারণ একটা দিনে আমি দুপুরের খাওয়ার আগে জরুরি কাজগুলো সেরে ফেলি আর বাকিগুলোর পরিকল্পনা করি।",
