        "workplace|1:1|3|p0": "আমাদের সদর দফতর বেঙ্গালুরুতে, কিন্তু আমাদের বেশিরভাগ কর্মী হুব্বল্লিতে।",
        "workplace|1:1|3|p1": "আমরা একটা ছোট স্টার্টআপ, ক্লিনিকের জন্য বিলিং সফটওয়্যার বানাই।",
        "workplace|1:1|3|p2": "মাইসুরুর কাছে আমাদের কারখানা ভারতের বেশিরভাগ টু-হুইলার ব্র্যান্ডের জন্য ব্রেকের যন্ত্রাংশ উৎপাদন করে।",
        "workplace|1:1|3|p3": "গ্রামীণ স্বাস্থ্যসেবায় আমাদের দক্ষতাই আমাদের আলাদা করে তোলে।",
        "workplace|1:1|3|p4": "ছোট শহরের দোকানগুলোকে অনলাইনে বিক্রি শুরু করতে সাহায্য করায় আমরা বিশেষজ্ঞ।",
        "workplace|1:1|4|title": "তুমি আসলে কী কাজ করো?",
        "workplace|1:1|4|text": "ধারওয়াড়ে এক পারিবারিক বিয়েতে নিখিলের কাকা তাকে জিজ্ঞেস করলেন সে আসলে অফিসে কী কাজ করে। নিখিল বুঝিয়ে বলল যে সে এমন একটা স্টার্টআপে কাজ করে যারা কৃষকদের জন্য মাটির সেন্সর বানায়। কোম্পানির সদর দফতর বেঙ্গালুরুতে, কিন্তু সেন্সরগুলো উৎপাদন হয় হুব্বল্লির কাছে একটা ছোট কারখানায়। তার পদ প্রোডাক্ট ইঞ্জিনিয়ার, আর সে টেস্টিং বিভাগে আছে। তার মূল কাজ হল প্রতিটা নতুন সেন্সর কৃষকদের কাছে যাওয়ার আগে পরীক্ষা করা। সে দু'জন জুনিয়র ইঞ্জিনিয়ারের তত্ত্বাবধানও করে, আর কারখানার দলের প্রশ্নগুলো সামলায়। কাকা হেসে বললেন কোম্পানির নিশ্চয়ই বিশাল কর্মীবাহিনী। নিখিল হেসে বলল সেখানে মাত্র চল্লিশ জন লোক, কিন্তু তাদের প্রত্যেকের সত্যিকারের দক্ষতা আছে।",
        "workplace|1:1|4|q0": "নিখিলের কোম্পানি কী বানায়?",
