        "workplace|1:1|5|title": "তা, আপনি কী করেন?",
        "workplace|1:1|5|scenario": "বেঙ্গালুরুর একটা বিজনেস ইভেন্টে অনন্যা আর ফারহানের প্রথম দেখা হয়, আর তারা নিজেদের কাজ নিয়ে কথা বলে।",
        "workplace|1:1|5|l0": "নমস্কার, আমি সহ্যাদ্রি লজিস্টিকসের ফারহান। এই ইভেন্টে কী মনে করে?",
        "workplace|1:1|5|l1": "আলাপ করে ভালো লাগল। আমি অনন্যা। একটা ফিনটেক স্টার্টআপে আমি কাস্টমার সাপোর্ট দলের প্রধান।",
        "workplace|1:1|5|l2": "বাহ্। আপনাদের কোম্পানি ঠিক কী করে?",
        "workplace|1:1|5|l3": "আমরা একটা অ্যাপ বানিয়েছি, যেটা ছোট দোকানদারদের হিসেব রাখতে আর ডিজিটাল পেমেন্ট নিতে সাহায্য করে।",
        "workplace|1:1|5|l4": "আর আপনার একটা সাধারণ দিন কেমন কাটে?",
        "workplace|1:1|5|l5": "দলের সঙ্গে একটা ছোট্ট কল দিয়ে শুরু করি, তারপর কঠিন অভিযোগগুলো নিজেই সামলাই।",
        "workplace|1:1|5|l6": "বেশ চাপের কাজ মনে হচ্ছে। আপনার দল কত বড়?",
        "workplace|1:1|5|l7": "দুটো শিফটে বারো জন। আর আপনি? আপনার ভূমিকা কী?",
        "workplace|1:1|5|l8": "আমি রুট প্ল্যানার। মোটকথা, আমাদের ট্রাকগুলো যাতে সবচেয়ে তাড়াতাড়ি আর সস্তা রাস্তায় যায়, সেটা আমি দেখি।",
        "workplace|1:1|5|l9": "তাহলে আপনার জন্যই আমার পার্সেল সময়মতো আসে! যোগাযোগ রাখবেন।",
        "workplace|1:1|5|q0": "অনন্যার কোম্পানি কী বানিয়েছে?",
        "workplace|1:1|5|q0o0": "ছোট দোকানদারদের জন্য একটা অ্যাপ",
