        "workplace|2:1|0|w5": "অংশগ্রহণকারী",
        "workplace|2:1|1|p0": "যাঁরা কথা বলছেন না, তাঁরা দয়া করে নিজেদের মিউট করে রাখবেন?",
        "workplace|2:1|1|p1": "আমি এইমাত্র টিম চ্যাটে মিটিংয়ের লিঙ্কটা পাঠিয়েছি।",
        "workplace|2:1|1|p2": "রবি, তোমার ওয়েবক্যাম বন্ধ; এক মিনিটের জন্য চালু করবে?",
        "workplace|2:1|1|p3": "শুধু হোস্টই অংশগ্রহণকারীদের ওয়েটিং রুম থেকে ভেতরে আনতে পারেন।",
        "workplace|2:1|1|p4": "দয়া করে হেডসেট পরুন, যাতে আপনার পেছনের গাড়িঘোড়ার আওয়াজ আমরা শুনতে না পাই।",
        "workplace|2:1|2|w0": "অস্থির",
