        "workplace|2:1|2|w4": "রেকর্ডিং",
        "workplace|2:1|2|w5": "ফলো-আপ",
        "workplace|2:1|3|p0": "দুঃখিত, আমার সংযোগ অস্থির; আমি ভিডিওটা বন্ধ করে দিচ্ছি।",
        "workplace|2:1|3|p1": "কয়েক সেকেন্ডের ল্যাগ হচ্ছে, তাই চলুন একজনের কথার ওপর আরেকজন কথা না বলি।",
        "workplace|2:1|3|p2": "আপনার স্ক্রিন আটকে গেছে; আবার শেয়ার করবেন?",
        "workplace|2:1|3|p3": "প্রতিধ্বনি শুনতে পাচ্ছি; কারও ল্যাপটপের স্পিকার তাঁর মাইকের খুব কাছে।",
        "workplace|2:1|3|p4": "আজ সন্ধ্যার মধ্যে আমি রেকর্ডিং আর একটা ছোট ফলো-আপ ইমেল পাঠিয়ে দেব।",
        "workplace|2:1|4|title": "যে কল বারবার আটকে যাচ্ছিল",
        "workplace|2:1|4|text": "প্রতি সোমবার দীপা মাইসুরুর তার দল আর পুনের সেলস দলের মধ্যে একটা ভিডিও কলের হোস্ট হয়। গত সপ্তাহে কলটা খারাপভাবে শুরু হল। বারো জন অংশগ্রহণকারী যোগ দিলেন, কিন্তু তাঁদের তিনজন লিঙ্কটা খুলতেই পারলেন না। তারপর জোরে প্রতিধ্বনি শুরু হল, কারণ সুরেশ একই সময়ে ল্যাপটপ আর ফোন দুটো থেকেই যোগ দিয়েছিলেন। দীপা যখন স্ক্রিন শেয়ার করতে শুরু করল, সেটা আটকে গেল, আর তার গলা অনেকটা ল্যাগ নিয়ে পুনেতে পৌঁছচ্ছিল। সে শান্তভাবে সবাইকে মিউট করতে, ওয়েবক্যাম বন্ধ করতে আর হেডসেট ব্যবহার করতে বলল। সংযোগ ভালো হল, আর মিটিংটা মাত্র দশ মিনিট দেরিতে শেষ হল। সেদিন সন্ধ্যায় দীপা রেকর্ডিং আর একটা পরিষ্কার ফলো-আপ ইমেল পাঠাল, যাতে প্রতিটা সিদ্ধান্ত আর ডেডলাইনের তালিকা ছিল।",
        "workplace|2:1|4|q0": "জোরে প্রতিধ্বনি হচ্ছিল কেন?",
        "workplace|2:1|4|q0o0": "সুরেশ একসঙ্গে দুটো যন্ত্র থেকে যোগ দিয়েছিলেন",
        "workplace|2:1|4|q0o1": "দীপার হেডসেট খারাপ ছিল",
