        "workplace|2:1|5|title": "আমার স্ক্রিন দেখতে পাচ্ছেন?",
        "workplace|2:1|5|scenario": "কার্তিক হুব্বল্লির বাড়ি থেকে একটা অনলাইন প্রজেক্ট মিটিংয়ে যোগ দেয়। হোস্ট মীরা তাকে আওয়াজ আর স্ক্রিন নিয়ে সাহায্য করে।",
        "workplace|2:1|5|l0": "হাই কার্তিক, তোমাকে দেখতে পাচ্ছি, কিন্তু তুমি মিউটে আছ।",
        "workplace|2:1|5|l1": "দুঃখিত। এবার শুনতে পাচ্ছ?",
        "workplace|2:1|5|l2": "হ্যাঁ, একদম পরিষ্কার। তোমার স্ক্রিনটা শেয়ার করে টেস্টের ফলাফলগুলো একটু বুঝিয়ে বলবে?",
        "workplace|2:1|5|l3": "নিশ্চয়ই, এক সেকেন্ড। সবাই আমার স্ক্রিন দেখতে পাচ্ছেন?",
        "workplace|2:1|5|l4": "একটা স্প্রেডশিট দেখতে পাচ্ছি, কিন্তু মনে হচ্ছে ওটা আটকে গেছে।",
        "workplace|2:1|5|l5": "আমার সংযোগ বারবার কেটে যাচ্ছে। ভিডিওটা বন্ধ করে আবার চেষ্টা করি।",
        "workplace|2:1|5|l6": "অনেক ভালো, এবার নড়ছে। বলো।",
        "workplace|2:1|5|l7": "ধন্যবাদ। দেখতেই পাচ্ছ, এই সপ্তাহের নব্বই শতাংশ টেস্ট পাস করেছে।",
        "workplace|2:1|5|l8": "দারুণ কাজ। আমি এটা রেকর্ড করছি, যাতে পুনের দল পরে দেখে নিতে পারে।",
        "workplace|2:1|5|l9": "চমৎকার। কলের পরে ফেল করা টেস্টগুলো নিয়ে একটা ছোট ফলো-আপও পাঠিয়ে দেব।",
        "workplace|2:1|5|q0": "কার্তিকের প্রথম সমস্যা কী ছিল?",
