        "workplace|3:1|0|w5": "সংখ্যা",
        "workplace|3:1|1|p0": "আজ আমরা কী কী নিয়ে কথা বলব, তার একটা সংক্ষিপ্ত ধারণা দিয়ে শুরু করি।",
        "workplace|3:1|1|p1": "এই স্লাইডে দেখতেই পাচ্ছেন, মার্চের পরে বিক্রি দ্বিগুণ হয়েছে।",
        "workplace|3:1|1|p2": "রূপরেখাটা আমি সহজ রেখেছি: সমস্যা, সমাধান, খরচ আর সময়সীমা।",
        "workplace|3:1|1|p3": "এই চার্টে গত দু'বছরের আমাদের মাসিক সংখ্যাগুলো দেখা যাচ্ছে।",
        "workplace|3:1|1|p4": "বিশেষ করে একটা সংখ্যা তুলে ধরতে চাই: আমাদের খরচ বারো শতাংশ কমেছে।",
        "workplace|3:1|2|w0": "প্রজেক্টর",
        "workplace|3:1|2|w1": "মহড়া দেওয়া",
        "workplace|3:1|2|w2": "হ্যান্ডআউট",
        "workplace|3:1|2|w3": "স্পষ্ট করা",
        "workplace|3:1|2|w4": "শেষ করা",
        "workplace|3:1|2|w5": "সংক্ষেপে বলা",
        "workplace|3:1|3|p0": "কেউ প্রজেক্টরটা একটু দেখবেন? স্লাইডগুলো খুব অন্ধকার দেখাচ্ছে।",
        "workplace|3:1|3|p1": "পুরো বক্তৃতাটা আমি দু'বার মহড়া দিয়েছি, তাই ঠিক কতক্ষণ লাগে জানি।",
        "workplace|3:1|3|p2": "সব সংখ্যা দেওয়া একটা হ্যান্ডআউট আছে, তাই আপনাদের নোট নেওয়ার দরকার নেই।",
        "workplace|3:1|3|p3": "ভালো প্রশ্ন; মোট খরচ বলতে আমি কী বুঝিয়েছি, সেটা স্পষ্ট করি।",
        "workplace|3:1|3|p4": "শেষ করার আগে, এক মিনিটে তিনটে মূল কথা সংক্ষেপে বলে নিই।",
        "workplace|3:1|4|title": "রেখার বড় দিন",
        "workplace|3:1|4|text": "হুব্বল্লির মার্কেটিং এক্সিকিউটিভ রেখাকে কোম্পানির ডিরেক্টরদের সামনে বছরের ফলাফল উপস্থাপন করতে হত। সে একটা সহজ রূপরেখা তৈরি করল আর মাত্র আটটা স্লাইড বানাল, প্রত্যেকটায় একটা করে পরিষ্কার চার্ট। আগের রাতে সে বোনের সামনে পুরো বক্তৃতাটা তিনবার মহড়া দিল। সেদিন শুরু করার পাঁচ মিনিট আগে মিটিং রুমের প্রজেক্টর কাজ করা বন্ধ করে দিল। ভাগ্যিস রেখা সব জরুরি সংখ্যা দিয়ে হ্যান্ডআউট ছাপিয়ে এনেছিল। সে একটা সংক্ষিপ্ত ধারণা দিয়ে শুরু করল, তারপর ডেলিভারির খরচ কতটা কমেছে তা তুলে ধরল। একজন ডিরেক্টর বেলগাভির নতুন দোকানটা নিয়ে জিজ্ঞেস করলে সে শান্তভাবে সংখ্যাগুলো স্পষ্ট করে দিল। তিনটে মূল কথা সংক্ষেপে বলে সে শেষ করল, আর ডিরেক্টররা এত পরিষ্কারভাবে বলার জন্য তাকে ধন্যবাদ দিলেন।",
