        "workplace|4:1|3|p4": "আমি আশ্বাস দিচ্ছি, বদলি জিনিস শুক্রবারের মধ্যে আপনার কাছে পৌঁছবে; এটা আমার নিজের প্রতিশ্রুতি।",
        "workplace|4:1|4|title": "যে মেনু কার্ড কখনও এল না",
        "workplace|4:1|4|text": "ইমরান বেঙ্গালুরুর একটা ছাপাখানা কোম্পানিতে ক্লায়েন্টদের অ্যাকাউন্ট সামলায়। এক সোমবার মাইসুরুতে হোটেল চালান এমন মিসেস শেট্টি তাকে ফোন করলেন, খুব বিরক্ত হয়ে। কোটেশনে এক সপ্তাহের মধ্যে ডেলিভারির কথা থাকলেও তাঁর নতুন মেনু কার্ড আসেনি। ইমরান মাঝখানে না থামিয়ে সব শুনল, তারপর ঠিক বুঝেছে কি না নিশ্চিত হতে তাঁর চাহিদাগুলো আবার বলল। সে জানতে পারল যে চালানে একটা ভুলের জন্য অর্ডারটা কখনও পাঠানোই হয়নি। সে সমস্যাটা ম্যানেজারকে জানাল আর সেদিন বিকেলেই কুরিয়ারের ব্যবস্থা করল। দেরির ক্ষতিপূরণ হিসেবে কোম্পানি মিসেস শেট্টির বিল থেকে দশ শতাংশ কমিয়ে দিল। ইমরান তাঁকে আশ্বাস দিল যে ভবিষ্যতের অর্ডারগুলো সে নিজে দেখবে, আর মিসেস শেট্টি কোম্পানির সঙ্গেই থেকে গেলেন।",
