        "workplace|4:1|5|l5": "সামনের মাসের পনেরো তারিখের মধ্যে। ওই তারিখটা আমাদের কাছে খুব জরুরি।",
        "workplace|4:1|5|l6": "বুঝেছি। শুক্রবারের মধ্যে দুটো বিকল্পসহ একটা প্রস্তাব আর কোটেশন পাঠিয়ে দেব।",
        "workplace|4:1|5|l7": "আপনাদের দল কি জায়গায় গিয়ে লাগানোর কাজটাও করে দেবে?",
        "workplace|4:1|5|l8": "হ্যাঁ, লাগানোর খরচ ধরা আছে। আর আশ্বাস দিচ্ছি, আমরা আপনার সময়সীমার মধ্যেই কাজ শেষ করব।",
        "workplace|4:1|5|l9": "দারুণ। তাহলে আপনার প্রস্তাবের অপেক্ষায় রইলাম।",
