        "workplace|5:1|1|p0": "আমার খুব জ্বর, তাই আজ অসুস্থতার ছুটি নিতে চাই।",
        "workplace|5:1|1|p1": "ভাইয়ের কলেজে ভর্তির জন্য শুক্রবার কি আধবেলা ছুটি নিতে পারি?",
        "workplace|5:1|1|p2": "ট্রেনের টিকিট কাটার আগে দেখে নিই আমার কত ছুটি বাকি আছে।",
        "workplace|5:1|1|p3": "ম্যানেজার দশ থেকে চোদ্দো তারিখ পর্যন্ত আমার ছুটি মঞ্জুর করেছেন।",
        "workplace|5:1|1|p4": "সোমবার অনুপস্থিত থাকার জন্য দুঃখিত; বাকি কাজ সারতে কাল কি বাড়ি থেকে কাজ করতে পারি?",
