        "workplace|5:1|2|w4": "নমনীয়",
        "workplace|5:1|2|w5": "আগে থেকে",
        "workplace|5:1|3|p0": "সামনের শনিবার আমার সঙ্গে শিফট অদলবদল করতে তোমার আপত্তি আছে?",
        "workplace|5:1|3|p1": "আমি যখন থাকব না, প্রিয়া আমার কলগুলো সামলে দিতে রাজি হয়েছে।",
        "workplace|5:1|3|p2": "বৃহস্পতিবার আমি ঠিকমতো দায়িত্ব বুঝিয়ে দেব, যাতে কিছু বাদ না পড়ে।",
        "workplace|5:1|3|p3": "আমাদের রিভিউটা কি পরের সপ্তাহে সরানো যায়? সোমবার আমি ছুটিতে।",
        "workplace|5:1|3|p4": "অন্তত এক সপ্তাহ আগে থেকে বললে আমাদের ম্যানেজার যথেষ্ট নমনীয়।",
        "workplace|5:1|4|title": "উডুপিতে বিয়ে",
        "workplace|5:1|4|text": "সৌম্যা বেঙ্গালুরুতে একটা ব্যাংকের হেড অফিসে পেমেন্টস দলে কাজ করে। উডুপিতে তার খুড়তুতো বোনের বিয়ে পড়ল মার্চের শেষ সপ্তাহে, বছরের সবচেয়ে ব্যস্ত সময়ে। সে দেখল তার এখনও ন'দিন ছুটি বাকি আছে। তিন সপ্তাহ আগে থেকে সে ম্যানেজার মিস্টার ভটের কাছে চার দিনের ছুটি চাইল, আর ভদ্রভাবে কারণটা বুঝিয়ে বলল। বিয়ের পরের দিন সে বাড়ি থেকে কাজ করার প্রস্তাবও দিল। মিস্টার ভট নমনীয় ছিলেন, তবে জানতে চাইলেন মাসের শেষের রিপোর্টগুলো কে সামলাবে। সৌম্যা সহকর্মী রাকেশের সঙ্গে দুটো শিফট অদলবদল করল, আর যাওয়ার আগে পুরো দায়িত্ব বুঝিয়ে দেওয়ার কথা দিল। তার পরিকল্পনায় খুশি হয়ে মিস্টার ভট সেদিন বিকেলেই ছুটি মঞ্জুর করলেন।",
        "workplace|5:1|4|q0": "সৌম্যার ছুটির দরকার ছিল কেন?",
