        "workplace|5:1|5|title": "ভোরবেলার ফোন",
        "workplace|5:1|5|scenario": "মা অসুস্থ বলে অরুণ খুব সকালে তার টিম লিড শালিনীকে ফোন করে।",
        "workplace|5:1|5|l0": "সুপ্রভাত, শালিনী। এত সকালে ফোন করার জন্য দুঃখিত। এক মিনিট সময় হবে?",
        "workplace|5:1|5|l1": "নিশ্চয়ই, অরুণ। সব ঠিক আছে তো?",
        "workplace|5:1|5|l2": "ঠিক নয়। কাল রাতে মা পড়ে গেছেন, কয়েকটা পরীক্ষার জন্য ওঁকে হাসপাতালে নিয়ে যেতে হবে।",
        "workplace|5:1|5|l3": "ইশ, শুনে খারাপ লাগল। মায়ের খেয়াল রেখো। গোটা দিনটাই লাগবে?",
        "workplace|5:1|5|l4": "মনে হয় হ্যাঁ। আজ ছুটি নিতে চাই, আর হয়তো কাল বাড়ি থেকে কাজ করব।",
        "workplace|5:1|5|l5": "ঠিক আছে। তিনটের ক্লায়েন্ট কলের কী হবে?",
        "workplace|5:1|5|l6": "দীপক প্রজেক্টটা ভালো জানে। আমি ওকে আগেই বলেছি, ও খুশি মনে সামলে দেবে।",
        "workplace|5:1|5|l7": "বেশ। ওকে তোমার নোটগুলো পাঠিয়ে দাও, আর সময় পেলে পোর্টালে ছুটির আবেদন কোরো।",
        "workplace|5:1|5|l8": "এক ঘণ্টার মধ্যে করে দেব। বোঝার জন্য ধন্যবাদ, শালিনী।",
        "workplace|5:1|5|l9": "কোনো ব্যাপার না। আশা করি তোমার মা তাড়াতাড়ি সেরে উঠবেন।",
