        "workplace|6:1|1|p0": "সব মিলিয়ে, এ বছর তোমার কর্মদক্ষতা খুব ভালো ছিল।",
        "workplace|6:1|1|p1": "রেগে যাওয়া গ্রাহকদের তুমি যেভাবে শান্তভাবে সামলাও, সেটাই তোমার সবচেয়ে বড় শক্তির দিক।",
        "workplace|6:1|1|p2": "কালকের প্রেজেন্টেশন নিয়ে তোমাকে কিছু গঠনমূলক মতামত দিতে পারি?",
        "workplace|6:1|1|p3": "আমার আত্মমূল্যায়নে আমি সময় সামলানোকে একটা দুর্বলতা হিসেবে লিখেছি।",
        "workplace|6:1|1|p4": "সময়মতো মাইসুরু শাখা চালু করাটা আমাদের দলের কাছে সত্যিকারের একটা মাইলফলক ছিল।",
