        "workplace|6:1|3|p0": "আমি ডেটা অ্যানালিসিসে দক্ষতা বাড়াতে চাই; কোম্পানি কি একটা ছোট কোর্সের খরচ দিতে পারবে?",
        "workplace|6:1|3|p1": "আমার পরামর্শদাতা বললেন লিড পদে আবেদনের আগে একটা ক্লাউড সার্টিফিকেশন করে নিতে।",
        "workplace|6:1|3|p2": "তোমার ম্যানেজার মনে করেন দু'বছরের মধ্যে একটা দল চালানোর সম্ভাবনা তোমার আছে।",
        "workplace|6:1|3|p3": "এ বছর দলের সবাই অন্তত আট শতাংশ বেতনবৃদ্ধি পাবে।",
        "workplace|6:1|3|p4": "আমার বিশ্বাস আমি পদোন্নতির যোগ্য, আর পরের ধাপ কী, তা নিয়ে কথা বলতে চাই।",
        "workplace|6:1|4|title": "মূল্যায়নের দিন",
        "workplace|6:1|4|text": "প্রতি এপ্রিলে ম্যাঙ্গালুরুতে ফরিদার কোম্পানিতে বার্ষিক মূল্যায়নের মিটিং হয়। নিজের মিটিংয়ের আগে সে একটা সৎ আত্মমূল্যায়ন লিখল, যাতে তার শক্তির দিকগুলো আর একটা স্পষ্ট দুর্বলতা ছিল: সে খুব কমই সাহায্য চাইত। তার ম্যানেজার মিস্টার রাও শুরুতেই নতুন বিলিং সিস্টেমে তার কর্মদক্ষতার প্রশংসা করলেন, যা দলের কাছে একটা বড় মাইলফলক ছিল। তারপর তিনি সমস্যাগুলো আরও আগে জানানোর ব্যাপারে তাকে কিছু গঠনমূলক মতামত দিলেন। ফরিদা তাঁকে ধন্যবাদ দিল আর প্রজেক্ট ম্যানেজমেন্টে ট্রেনিং চাইল। মিস্টার রাও একটা সার্টিফিকেশন কোর্সের খরচ দিতে আর তার জন্য একজন সিনিয়র পরামর্শদাতা খুঁজে দিতে রাজি হলেন। তিনি বললেন একদিন দল চালানোর সম্ভাবনা তার আছে, আর সে একটা ভালো বেতনবৃদ্ধির যোগ্য। সামনের বছরের একটা পরিষ্কার পরিকল্পনা নিয়ে ফরিদা মিটিং থেকে বেরোল।",
