        "workplace|6:1|5|l0": "আসার জন্য ধন্যবাদ, রমেশ। তোমার আত্মমূল্যায়ন দিয়ে শুরু করি। বছরটা কেমন গেল বলে তোমার মনে হয়?",
        "workplace|6:1|5|l1": "আমার মনে হয় ভালোই গেছে। আমরা সময়মতো পেমেন্ট অ্যাপটা দিয়েছি, আর আমি দু'জন নতুন কর্মীকে ট্রেনিং দিয়েছি।",
        "workplace|6:1|5|l2": "একমত। অ্যাপে তোমার কাজ দুর্দান্ত ছিল, আর ক্লায়েন্ট আলাদা করে তোমার কাজের কথা বলেছেন।",
        "workplace|6:1|5|l3": "শুনে খুব ভালো লাগল। আমার কি কিছু উন্নতি করা দরকার?",
        "workplace|6:1|5|l4": "শুধু একটা ব্যাপার। মিটিংয়ে ভালো আইডিয়া থাকলেও তুমি প্রায়ই চুপ করে থাকো। আমি চাই তুমি আরও বেশি মুখ খোলো।",
        "workplace|6:1|5|l5": "ঠিক কথা। আমি আরও আগে আইডিয়াগুলো বলার চেষ্টা করব। আমি কি কিছু ট্রেনিংও চাইতে পারি?",
        "workplace|6:1|5|l6": "নিশ্চয়ই। কী ভাবছ?",
        "workplace|6:1|5|l7": "পাবলিক স্পিকিংয়ের একটা কোর্স, আর হয়তো সিনিয়র দল থেকে একজন পরামর্শদাতা।",
        "workplace|6:1|5|l8": "দুটোই ভালো ভাবনা। এই সপ্তাহে এইচআর-এর সঙ্গে কথা বলব। এভাবেই চালিয়ে যাও, সামনের বছর টিম লিডের পদ নিয়ে কথা বলা যাবে।",
