        "opinions|1:1|1|p0": "আমার মতে, প্রত্যেক বাচ্চার অন্তত একটা বাদ্যযন্ত্র শেখা উচিত।",
        "opinions|1:1|1|p1": "আমার দিক থেকে, বাসের নতুন সময়সূচি অনেক ভালো হয়েছে।",
        "opinions|1:1|1|p2": "ক্লাসরুমে মোবাইল ফোন নিয়ে তোমার অবস্থান কী?",
        "opinions|1:1|1|p3": "উনি এমন দৃঢ় বিশ্বাস নিয়ে কথা বললেন যে ঘরের কেউ ওঁর সঙ্গে তর্ক করল না।",
