        "opinions|1:1|3|p0": "তোমার যুক্তি পরিষ্কার, কিন্তু আমি কয়েকটা উদাহরণ শুনতে চাই।",
        "opinions|1:1|3|p1": "ছোট শহরে থাকতে খুব ভালো লাগতে পারে; যেমন উডুপি, শান্ত আর পরিষ্কার।",
        "opinions|1:1|3|p2": "ওটা শুধুই একটা অনুমান; এর পক্ষে তোমার কাছে কোনো তথ্য আছে?",
        "opinions|1:1|3|p3": "আমার মন বলছিল যে জঙ্গলের ভেতর দিয়ে শর্টকাটটা ভালো বুদ্ধি নয়।",
        "opinions|1:1|3|p4": "সব মিলিয়ে, আমার মনে হয় অনলাইন ক্লাস আমাদের আশার চেয়ে ভালো কাজ করেছে।",
        "opinions|1:1|4|title": "ধারওয়াড়ে বিতর্ক",
        "opinions|1:1|4|text": "প্রতি বছর ধারওয়াড়ের একটা কলেজে ছাত্রছাত্রীদের কাছে গুরুত্বপূর্ণ কোনো প্রশ্ন নিয়ে বিতর্ক হয়। এ বছরের বিষয় ছিল পরীক্ষার বদলে প্রজেক্ট চালু করা উচিত কি না। মেঘনা প্রথমে বলল, আর তার মতে প্রজেক্ট ছাত্রছাত্রীদের মুখস্থ করার বদলে ভাবতে শেখায়। সে নিজের স্কুলের একটা পরিষ্কার উদাহরণ দিল, যেখানে বিজ্ঞানের একটা প্রজেক্ট তাকে যেকোনো পরীক্ষার চেয়ে বেশি শিখিয়েছিল। রোহন একমত হল না; সত্যি বলতে, সে বলল, প্রজেক্ট অন্যায্য হতে পারে, কারণ শেষে কয়েকজনকেই সব কাজ করতে হয়। তার যুক্তি জোরালো ছিল, কিন্তু তার কয়েকটা কথা তর্কসাপেক্ষ ছিল। সব মিলিয়ে বিচারকদের মনে হল মেঘনা ভালো উদাহরণ দিয়েছে। বিতর্কের পরে দুই বন্ধু চা খেতে গেল, আর আরও এক ঘণ্টা মজা করে তর্ক চালিয়ে গেল।",
        "opinions|1:1|4|q0": "বিতর্কের বিষয় কী ছিল?",
        "opinions|1:1|4|q0o0": "পরীক্ষার বদলে প্রজেক্ট চালু করা উচিত কি না",
