        "opinions|1:1|5|l0": "কিরণ, মা একটা নতুন নিয়ম চান: রাতের খাবার টেবিলে কোনো ফোন নয়। তোর কী মনে হয়?",
        "opinions|1:1|5|l1": "সত্যি বলতে, একটু বেশি কড়া মনে হচ্ছে। মাঝে মাঝে বন্ধুদের উত্তর দিতে হয়।",
        "opinions|1:1|5|l2": "আমার দিক থেকে, রাতের খাওয়াটাই একমাত্র সময় যখন আমরা সবাই একসঙ্গে বসি।",
        "opinions|1:1|5|l3": "সেটা ঠিক, কিন্তু কোনো জরুরি মেসেজ এলে?",
        "opinions|1:1|5|l4": "তখন এক মিনিটের জন্য উঠে যেতে পারিস। যেমন, বাবা অফিসের ফোন এলে তাই করেন।",
        "opinions|1:1|5|l5": "হুম। সব মিলিয়ে মনে হয় নিয়মটা ঠিকই আছে, কিন্তু শুধু রাতের খাবারে, দুপুরে নয়।",
        "opinions|1:1|5|l6": "আমার মতে, এটা বেশ ভালো রফা। চল, মাকে একসঙ্গে বলি?",
        "opinions|1:1|5|l7": "হ্যাঁ, কিন্তু সবাইকে জানতে হবে যে আমি অনেক তর্কের পরেই রাজি হয়েছি!",
        "opinions|1:1|5|l8": "লিখে রাখলাম। মহামান্য, আপনার অবস্থান শোনা হয়েছে।",
