        "opinions|2:1|1|p1": "এটা ন্যায্য কথা; খরচের কথাটা আমি ভাবিনি।",
        "opinions|2:1|1|p2": "আমি পুরোপুরি একমত; রবিবারেও লাইব্রেরি খোলা থাকা উচিত।",
        "opinions|2:1|1|p3": "মেনে নিচ্ছি তুমিই ঠিক ছিলে; সকলেশপুর দিয়ে রাস্তাটা অনেক তাড়াতাড়ি হয়েছিল।",
