        "opinions|2:1|3|p0": "সম্মান রেখেই বলছি স্যার, আমার মনে হয় তথ্য অন্য কথা বলছে।",
        "opinions|2:1|3|p1": "আমি ভিন্নমত পোষণ করি; মলের চেয়ে পুরোনো বাজারের নিজস্বতা অনেক বেশি।",
        "opinions|2:1|3|p2": "দু'পক্ষের কথা শোনার পর প্রধান শিক্ষিকা তাঁর সিদ্ধান্ত আবার ভেবে দেখতে রাজি হলেন।",
        "opinions|2:1|3|p3": "প্রথমে ও এই ট্রিপের বিরুদ্ধে ছিল, কিন্তু পরে ওর মত বদলে গেল।",
        "opinions|2:1|3|p4": "আমরা দুজনেই খোলা মনের, তাই সহজেই মতভেদ মেনে নিতে পারি।",
        "opinions|2:1|4|title": "স্কুলের শেষ ট্রিপ",
        "opinions|2:1|4|text": "হাসানের দ্বাদশ শ্রেণিকে স্কুলের শেষ ট্রিপের জন্য একটা জায়গা বাছতে হত। নিখিল সমুদ্রসৈকতের জন্য গোকর্ণ যেতে চাইছিল, কিন্তু দিব্যা ইতিহাসের জন্য হাম্পি যেতে চাইছিল। প্রথমে দুজনে একমত হতে পারছিল না, আর আলোচনাটা চেঁচামেচিতে গড়াল। তারপর দিব্যা বলল, 'সম্মান রেখেই বলছি, সমুদ্রসৈকতে মজা ঠিকই, কিন্তু হাম্পি আমাদের সারা জীবন মনে থাকবে।' নিখিল মেনে নিল যে তার কথাটা ন্যায্য, কিন্তু গরম নিয়ে তার চিন্তা ছিল। তাদের শিক্ষক একটা মিলের জায়গা খুঁজে পেতে সাহায্য করলেন: ঠান্ডা সকালে তারা হাম্পি ঘুরবে, আর বিকেলে তুঙ্গভদ্রা নদীর ধারে বিশ্রাম নেবে। শেষে নিখিলের মত বদলে গেল, আর সে নিজেই হাম্পির পক্ষে ভোট দিল। এক মাস পরে সবাই একমত হল যে এটাই তাদের জীবনের সেরা ট্রিপ ছিল।",
