        "opinions|2:1|5|scenario": "ম্যাঙ্গালুরুর একটা কলেজের ফেস্ট কমিটির দুই সদস্য পূজা আর সমীর টাকা কীভাবে খরচ হবে তা নিয়ে একমত নয়।",
        "opinions|2:1|5|l0": "সমীর, শুনলাম তুমি কলেজ ফেস্টে একজন ফিল্মস্টারকে ডাকতে চাও। সত্যি?",
        "opinions|2:1|5|l1": "হ্যাঁ! বড় নাম এলে বিশাল ভিড় হবে। তোমার তা মনে হয় না?",
        "opinions|2:1|5|l2": "কিছুটা হ্যাঁ। কিন্তু সম্মান রেখেই বলছি, স্টারের ফি-তেই আমাদের অর্ধেক টাকা চলে যাবে।",
        "opinions|2:1|5|l3": "ন্যায্য কথা। তবুও স্টার ছাড়া ফেস্টটা একটু সাধারণ লাগে।",
        "opinions|2:1|5|l4": "আমি ভিন্নমত পোষণ করি। গত বছর উডুপির যক্ষগান দলটাই ছিল ফেস্টের সেরা অংশ।",
        "opinions|2:1|5|l5": "হুম, ওই অনুষ্ঠানটা নিয়ে আমি পুরোপুরি একমত। শেষে সবাই নাচছিল।",
        "opinions|2:1|5|l6": "তাহলে ওদের আবার ডাকি না কেন, আর বাকি টাকাটা ভালো খাবার আর আলোয় খরচ করি?",
        "opinions|2:1|5|l7": "আচ্ছা, তুমি আমার মত বদলে দিলে। আবার ভেবে দেখব, আর কাল কমিটির সঙ্গে কথা বলব।",
        "opinions|2:1|5|l8": "এত খোলা মনে ভাবার জন্য ধন্যবাদ। জানি এটা তোমার সবচেয়ে প্রিয় আইডিয়া ছিল।",
        "opinions|2:1|5|l9": "আচ্ছা, কোন ফিল্মস্টার সেরা, সেটা নিয়ে আমরা মতভেদ মেনে নিতেই পারি!",
