        "opinions|3:1|3|p1": "আন্তঃস্কুল কুইজ জেতাটা আমাদের গোটা ক্লাসের কাছে একটা অবিস্মরণীয় মুহূর্ত ছিল।",
        "opinions|3:1|3|p2": "ওই পরীক্ষায় ফেল করাটা ছিল জীবনের মোড় ঘোরানো মুহূর্ত; তারপর থেকে আমি মন দিয়ে পড়তে শুরু করি।",
