        "opinions|3:1|4|text": "শ্রেয়া কোডাগুর একটা ছোট গ্রামে বড় হয়েছে, যেখানে তার পরিবার কফি চাষ করত। ছেলেবেলার বেশিরভাগটাই তার আবছা ভাবে মনে আছে, কিন্তু একটা দিন এখনও তার মনে জীবন্ত। তার যখন দশ বছর বয়স, প্রবল বৃষ্টিতে নদীতে বান এল, আর স্কুলবাস ব্রিজ পার হতে পারল না। ঠান্ডার মধ্যে বাচ্চারা ঘণ্টার পর ঘণ্টা অপেক্ষা করল, শেষে পোন্নাপ্পা নামে এক কৃষক তাঁর ট্র্যাক্টর নিয়ে এলেন। দুজন-তিনজন করে তিনি তিরিশটা বাচ্চাকেই জল পার করিয়ে দিলেন। তিনি যে ছোট তোয়ালেটা দিয়েছিলেন, শ্রেয়া সেটা আজও স্মৃতিচিহ্ন হিসেবে রেখে দিয়েছে। জোরে বৃষ্টি হলেই হঠাৎ সেই সন্ধ্যার স্মৃতির ঝলক তার মনে ভেসে ওঠে। তার কাছে ওটা ছিল জীবনের মোড় ঘোরানো মুহূর্ত: সেদিনই সে ঠিক করেছিল যে সে-ও মানুষকে সাহায্য করেই জীবন কাটাবে।",
        "opinions|3:1|4|q0": "স্কুলবাস কেন বাচ্চাদের বাড়ি নিয়ে যেতে পারল না?",
