        "opinions|4:1|3|p1": "দুবাইয়ে দু'বছর কাটানোর পর গ্রামের জন্য ওর মনে গভীর আকুলতা জাগল।",
        "opinions|4:1|3|p2": "কাল রেজাল্ট বেরোবে, তবে আমি বেশ আশাবাদী, দুগ্গা দুগ্গা!",
        "opinions|4:1|3|p3": "ছুটি নিয়ে দিবাস্বপ্ন দেখা থামাও, আগে প্রজেক্টটা শেষ করো।",
