        "opinions|4:1|5|scenario": "ইমরান এইমাত্র তার এন্ট্রান্স পরীক্ষার রেজাল্ট দেখেছে। কলবুর্গির লাইব্রেরির বাইরে তার বন্ধু কবিতার সঙ্গে দেখা হয়।",
        "opinions|4:1|5|l0": "ইমরান, তোমাকে মনমরা দেখাচ্ছে। এন্ট্রান্সের রেজাল্ট বেরিয়েছে?",
