        "opinions|4:1|5|l2": "খুব খারাপ লাগছে। কিন্তু চার নম্বর তো খুব কাছাকাছি। বোঝাই যাচ্ছে তুমি বিষয়গুলো ভালো জানো।",
        "opinions|4:1|5|l3": "ইশ, যদি ওই দু'মাস ভিডিও গেমে নষ্ট না করতাম!",
        "opinions|4:1|5|l4": "পিছন ফিরে দেখলে সবকিছুই সোজা মনে হয়। এখন তো আর বদলানো যাবে না, তাই মন থেকে ছেড়ে দেওয়ার চেষ্টা করো।",
        "opinions|4:1|5|l5": "জানি, কিন্তু মা-বাবা খুব আশা করেছিলেন। মনে হচ্ছে ওঁদের হতাশ করলাম।",
        "opinions|4:1|5|l6": "ওঁদের সঙ্গে খোলাখুলি কথা বলো। সামনের বছর আবার পরীক্ষা দিতে পারবে; এটা একটা দ্বিতীয় সুযোগ।",
        "opinions|4:1|5|l7": "ঠিক বলেছ। আর এবার প্রথম দিন থেকেই একটা ঠিকঠাক রুটিন বানাব।",
        "opinions|4:1|5|l8": "দেখলে? এর মধ্যেই আশার আলো দেখা যাচ্ছে। তোমাকে নিয়ে আমি আশাবাদী।",
        "opinions|4:1|5|l9": "ধন্যবাদ, কবিতা। সামনের বছর নিজেকে প্রমাণ করার জন্য আমি এখন সত্যিই মুখিয়ে আছি।",
        "opinions|4:1|5|q0": "ইমরান কত নম্বরের জন্য কাট-অফ পেরোতে পারেনি?",
