        "opinions|5:1|1|p0": "এক টুকরো ছোট জমি নিয়ে দুই ভাইয়ের মধ্যে ঝগড়া হয়েছিল।",
        "opinions|5:1|1|p1": "পুরোটাই ভুল বোঝাবুঝি ছিল; ও কখনও তোমাকে কষ্ট দিতে চায়নি।",
        "opinions|5:1|1|p2": "এক সপ্তাহ কথা বন্ধ থাকার পর দুই বন্ধু শেষমেশ এক কাপ চায়ে মিটমাট করে নিল।",
        "opinions|5:1|1|p3": "মনে ক্ষোভ পুষে রাখলে শুধু তোমারই কষ্ট; ক্ষমা করে এগিয়ে যাওয়ার চেষ্টা করো।",
        "opinions|5:1|1|p4": "মা-বাবা তর্ক করলে আমি কখনও কারও পক্ষ নিই না; শুধু দুজনের জন্য চা বানাই।",
        "opinions|5:1|2|w0": "বিশ্বাসযোগ্য",
