        "opinions|5:1|3|p0": "বিশ্বাসযোগ্য বন্ধু ঝগড়ার পরেও তোমার গোপন কথা গোপনই রাখে।",
        "opinions|5:1|3|p1": "আমি দিদিকে মনের কথা বলি, কারণ ও কখনও আমার বিচার করে না।",
        "opinions|5:1|3|p2": "প্রতি রবিবার একসঙ্গে রান্না করে বাবা আর আমার বন্ধন আরও মজবুত হয়েছে।",
        "opinions|5:1|3|p3": "আমরা যোগাযোগ রাখার কথা দিয়েছিলাম, কিন্তু কলেজের পরে ধীরে ধীরে দূরে সরে গেলাম।",
        "opinions|5:1|3|p4": "ভারতীয় বাড়িতে পারিবারিক বন্ধন প্রায়ই বহু প্রজন্ম ধরে মজবুত থাকে।",
        "opinions|5:1|4|title": "শিবমোগ্গার দুই বন্ধু",
        "opinions|5:1|4|text": "অরুণ আর প্রকাশ শিবমোগ্গায় পাশাপাশি বাড়িতে বড় হয়েছে, আর ক্রিকেট ব্যাট থেকে গোপন কথা পর্যন্ত সব ভাগ করে নিত। কলেজে তাদের মধ্যে তিক্ত ঝগড়া হল, যখন প্রকাশের মনে হল অরুণ তার গোপন কথা অন্যদের বলে দিয়েছে। পুরোটাই ছিল ভুল বোঝাবুঝি, কিন্তু অহংকারে দুজনের কেউই আগে ফোন করল না। পাঁচ বছর তারা কথা বলেনি, আর তাদের বন্ধুরা কারও পক্ষ নিতে রাজি হয়নি। অরুণের মা দুই ছেলেকেই ভালোবাসতেন, আর কখনও আশা ছাড়েননি যে তারা মিটমাট করে নেবে। প্রকাশের বোনের বিয়েতে শেষমেশ দুজনে মুখোমুখি দাঁড়াল। প্রকাশ বলল, 'একটা বোকা কারণে আমি মনে ক্ষোভ পুষে রেখেছি; আমায় ক্ষমা করে দে।' অরুণ তাকে জড়িয়ে ধরল, আর সেদিন থেকে তারা প্রতি সপ্তাহে যোগাযোগ রাখে।",
        "opinions|5:1|4|q0": "প্রকাশ অরুণের ওপর রেগে গিয়েছিল কেন?",
        "opinions|5:1|4|q0o0": "তার মনে হয়েছিল অরুণ তার গোপন কথা অন্যদের বলে দিয়েছে",
        "opinions|5:1|4|q0o1": "অরুণ তার ক্রিকেট ব্যাট ভেঙে ফেলেছিল",
