        "opinions|5:1|5|title": "মিটমাট",
        "opinions|5:1|5|scenario": "আকাশ বেলগাভিতে তার কলেজের বন্ধু স্মিতার সঙ্গে দেখা করতে যায়। এক সপ্তাহ ধরে স্মিতা তার সঙ্গে কথা বলেনি।",
        "opinions|5:1|5|l0": "স্মিতা, এক মিনিট কথা বলা যাবে? জানি তুমি আমার ওপর রেগে আছ।",
        "opinions|5:1|5|l1": "রেগে? তুমি আমার নাচের অনুষ্ঠানে আসবে বলে কথা দিয়েছিলে, আর একটা ফোন পর্যন্ত করোনি।",
        "opinions|5:1|5|l2": "তুমি ঠিক, আর আমি সত্যিই দুঃখিত। সেদিন সন্ধ্যায় ঠাকুমাকে হাসপাতালে নিয়ে যেতে হয়েছিল।",
        "opinions|5:1|5|l3": "সে কী! আমাকে বলোনি কেন? আমি ভেবেছিলাম তোমার কিছু যায় আসে না।",
        "opinions|5:1|5|l4": "ফোনের ব্যাটারি শেষ হয়ে গিয়েছিল, আর পরে বোঝাতে খুব লজ্জা লাগছিল। একটা বোকা ভুল বোঝাবুঝি।",
        "opinions|5:1|5|l5": "ইশ, যদি আগে বলতে। গোটা এক সপ্তাহ আমি মনে ক্ষোভ পুষে রেখেছি।",
        "opinions|5:1|5|l6": "বুঝতে পারছি। আমাকে ক্ষমা করবে? আমাদের বন্ধুত্ব আমার কাছে অনেক কিছু।",
        "opinions|5:1|5|l7": "অবশ্যই। আমার চেনা সবচেয়ে বিশ্বাসযোগ্য মানুষদের মধ্যে তুমি একজন। ঠাকুমা এখন কেমন আছেন?",
        "opinions|5:1|5|l8": "অনেক ভালো, ধন্যবাদ। বাড়ি ফিরেছেন, আর এর মধ্যেই সবাইকে হুকুম দিচ্ছেন!",
        "opinions|5:1|5|l9": "ঠিক ওঁর মতোই। পরের বার কথা দাও, ফোন বন্ধ থাকলেও যোগাযোগ রাখবে!",
