        "opinions|6:1|3|p0": "আমি সত্যিই দোটানায় পড়েছি: পুনের চাকরিটা নেব, নাকি বাড়িতেই থাকব?",
        "opinions|6:1|3|p1": "আর্ট পড়া আর পারিবারিক ব্যবসায় যোগ দেওয়ার মধ্যে ও দু'দিকের টানাপোড়েনে আছে।",
        "opinions|6:1|3|p2": "বড় কোনো সিদ্ধান্ত নিতে হলে কাকাই আমার মন খুলে কথা বলার সবচেয়ে ভালো মানুষ।",
        "opinions|6:1|3|p3": "ও ডাক্তারের সাবধানবাণী কানে তোলেনি, আর আবার অসুস্থ হয়ে পড়ল।",
        "opinions|6:1|3|p4": "ভালো করে ভেবে দেখো, আর অনলাইন রিভিউগুলো একটু সন্দেহ নিয়েই পড়ো।",
        "opinions|6:1|4|title": "ঠাকুমার পরামর্শ",
        "opinions|6:1|4|text": "উডুপির স্নেহা দোটানায় পড়েছিল: আমেদাবাদের একটা ডিজাইন কলেজে সে সুযোগ পেয়েছিল, কিন্তু মা-বাবা চাইছিলেন সে বাড়ির কাছাকাছি পড়ুক। নিজের স্বপ্ন আর পরিবারের মধ্যে সে দু'দিকের টানাপোড়েনে ভুগছিল, তাই সে ঠাকুমার কাছে গেল, যিনি সবসময় তার মন খুলে কথা বলার মানুষ। ঠাকুমা চুপ করে সব শুনলেন, তারপর বললেন, 'আমি তোর জায়গায় থাকলে তাড়াহুড়ো করে ঠিক করতাম না; ক'দিন ভেবে দেখ।' আত্মীয়দের মন্তব্য নিয়েও তিনি স্নেহাকে একটা উপদেশ দিলেন: ওগুলো একটু সন্দেহ নিয়েই শুনবি। 'আমার মোটা দাগের নিয়ম সোজা,' ঠাকুমা যোগ করলেন, 'এমন পথ বেছে নে যার জন্য ষাট বছর বয়সে আফসোস হবে না।' তারপর তিনি একটা পরামর্শ দিলেন: 'মা-বাবাকে কলেজের ওয়েবসাইট আর তোর পোর্টফোলিওটা দেখাস না কেন?' স্নেহা তাঁর কথা কানে তুলল, আর তার কাজ দেখে মা-বাবা রাজি হয়ে গেলেন। আজ সে প্রতি রবিবার ঠাকুমাকে ফোন করে তার ক্লাসের সব গল্প বলে।",
