        "opinions|6:1|5|scenario": "ধারওয়াড়ের প্রথম বর্ষের ছাত্র দীপক হস্টেলের রুমমেটকে নিয়ে পরামর্শ চাইতে তার খুড়তুতো দিদি শালিনীকে ফোন করে।",
        "opinions|6:1|5|l0": "শালিনীদি, একটা ব্যাপারে তোমার পরামর্শ চাইতে পারি? আর কার সঙ্গে কথা বলব বুঝতে পারছি না।",
