        "opinions|6:1|5|l6": "ভালো পরামর্শ। কিন্তু আসলে কী বলব?",
        "opinions|6:1|5|l7": "মোটা দাগের নিয়ম হল, ওর দোষ নয়, নিজের সমস্যার কথা বল। রাত এগারোটার পরে হেডফোন ব্যবহার করতে বলিস না কেন?",
        "opinions|6:1|5|l8": "এটা ন্যায্য মনে হচ্ছে। ভেবে দেখি, আর এই উইকেন্ডে ওর সঙ্গে কথা বলব।",
        "opinions|6:1|5|l9": "বেশ। আর বরং বেশি দেরি করিস না, নইলে পরীক্ষার হলে ঘুমিয়ে পড়বি!",
