        "society|1:1|3|p3": "পেজটা বারবার রিফ্রেশ করতে থাকো; ওরা প্রতি দশ মিনিটে একটা আপডেট দেয়।",
        "society|1:1|3|p4": "খবরটা শুনে তোমার প্রথম প্রতিক্রিয়া কী ছিল?",
        "society|1:1|4|title": "যে সেতু ভাঙেনি",
        "society|1:1|4|text": "এক সন্ধ্যায় মাইসুরু জুড়ে একটা মেসেজ ছড়িয়ে পড়ল যে শ্রীরঙ্গপত্তনের কাছের পুরোনো সেতুটা ভেঙে পড়েছে। কলেজ-ছাত্র রাহুল প্রায় সেটা তার পরিবারের গ্রুপে ফরোয়ার্ড করে ফেলছিল, কিন্তু থেমে গেল। সে একটা বিশ্বস্ত খবরের ওয়েবসাইট খুলল, আর এমন কোনো শিরোনাম পেল না। তার বদলে সে সেতুর কাছে দাঁড়িয়ে থাকা এক স্থানীয় সাংবাদিকের একটা ছোট আপডেট দেখল। তিনি এক প্রত্যক্ষদর্শীর সঙ্গে কথা বলেছিলেন, যিনি জানালেন রেলিংয়ের শুধু একটা ছোট অংশ নদীতে পড়ে গেছে। কেউ আহত হয়নি, আর সেতু তখনও খোলা ছিল। রাহুল বুঝল যে মেসেজটা একটা ছোট ঘটনাকে ফুলিয়ে-ফাঁপিয়ে তৈরি করা গুজব মাত্র। সে গ্রুপে আসল খবরটা দিল, আর সবাইকে শেয়ার করার আগে যাচাই করতে বলল।",
