        "society|1:1|5|l0": "ইমরান, আজ সকালের খবর দেখেছ? কাল রাতে বেঙ্গালুরুতে বিরাট ঝড় হয়েছে।",
        "society|1:1|5|l1": "শিরোনামটা দেখেছি, কিন্তু পুরো খবরটা পড়িনি। কী হয়েছিল?",
        "society|1:1|5|l2": "শুনলাম জয়নগরে দাঁড়িয়ে থাকা একটা বাসের ওপর বড় একটা গাছ পড়েছে। ভাগ্যিস বাসটা খালি ছিল।",
        "society|1:1|5|l3": "যাক বাবা। কেউ আহত হয়েছে?",
        "society|1:1|5|l4": "না। এক প্রত্যক্ষদর্শী সাংবাদিকদের বলেছেন, ড্রাইভার ঠিক এক মিনিট আগে চা খেতে নেমেছিলেন।",
        "society|1:1|5|l5": "দারুণ ভাগ্য বলতে হবে। একটা গুজবও শুনলাম যে মেট্রো বন্ধ হয়ে গিয়েছিল। সত্যি?",
        "society|1:1|5|l6": "শুধু এক ঘণ্টার জন্য। সর্বশেষ আপডেট বলছে সব লাইন আবার স্বাভাবিকভাবে চলছে।",
        "society|1:1|5|l7": "সত্যি বলতে, আমার প্রথম প্রতিক্রিয়া হল খারাপ পরিকল্পনাকে দোষ দেওয়া। বর্ষার আগে পুরোনো গাছগুলো পরীক্ষা করা হয় না কেন?",
        "society|1:1|5|l8": "আজকের সম্পাদকীয়তে ঠিক এই কথাই বলা হয়েছে। পুরসভা প্রতিটা পুরোনো গাছের সমীক্ষা করার কথা দিয়েছে।",
        "society|1:1|5|l9": "দেখা যাক, এবার কথাটা রাখে কি না।",
