        "society|2:1|1|p0": "আমার ঠাকুমা সত্তর বছর বয়সে স্মার্টফোন চালাতে শিখেছেন।",
        "society|2:1|1|p1": "অ্যাপ শুধু অফিশিয়াল স্টোর থেকে ডাউনলোড করুন, যেখানে-সেখানে লিঙ্ক থেকে কখনও নয়।",
        "society|2:1|1|p2": "পড়ার সময় বারবার মন সরে যাচ্ছিল বলে আমি নোটিফিকেশন বন্ধ করে দিয়েছি।",
        "society|2:1|1|p3": "পুরোনো ভিডিওতে স্টোরেজ ভরে গেছে বলে আমার ফোন বারবার আটকে যাচ্ছে।",
        "society|2:1|1|p4": "কোনো গোলমাল হলে কাজে লাগবে, তাই পেমেন্টের পেজের একটা স্ক্রিনশট নিয়ে রাখো।",
        "society|2:1|2|w0": "সোশ্যাল মিডিয়া",
