        "society|2:1|2|w4": "স্ক্রিন টাইম",
        "society|2:1|2|w5": "মন্তব্য",
        "society|2:1|3|p0": "ওর রান্নার ভিডিও ভাইরাল হয়ে গেল, আর এক রাতেই দশ হাজার ফলোয়ার বাড়ল।",
        "society|2:1|3|p1": "কোনো কোম্পানি পোস্টের জন্য টাকা দিলে ইনফ্লুয়েন্সারের সেটা সৎভাবে জানানো উচিত।",
        "society|2:1|3|p2": "আমি দিনে আমার স্ক্রিন টাইম দু'ঘণ্টার মধ্যে রাখার চেষ্টা করি।",
        "society|2:1|3|p3": "বাজে মন্তব্য গায়ে মেখো না; বেশিরভাগই অচেনা লোকের কাছ থেকে আসে।",
        "society|2:1|3|p4": "সোশ্যাল মিডিয়া আমাদের জুড়ে রাখে, কিন্তু একাকীও করে দিতে পারে।",
        "society|2:1|4|title": "ফোনহীন রবিবার",
        "society|2:1|4|text": "প্রতি সন্ধ্যায় জয়পুরের শর্মা পরিবার একই ঘরে বসত, কিন্তু কেউ আসলে কথা বলত না। প্রত্যেকে স্মার্টফোন নিয়ে ব্যস্ত থাকত, সোশ্যাল মিডিয়া স্ক্রল করত বা ভিডিও দেখত। এক রাতে বারো বছরের রিয়া তার স্ক্রিন টাইম দেখে চমকে উঠল: ছ'ঘণ্টা! সে একটা নতুন নিয়মের প্রস্তাব দিল: রবিবার সকালের জলখাবার থেকে রাতের খাবার পর্যন্ত কোনো ফোন নয়। বাবা প্রথমে হেসে উঠলেন, কারণ তাঁর ফোন সবসময় কাজের নোটিফিকেশনে ভরা থাকত। কিন্তু প্রথম ফোনহীন রবিবারে পরিবারের সবাই ক্যারম খেলল, একসঙ্গে রান্না করল, এমনকি দাদু-ঠাকুমার সঙ্গে দেখা করতেও গেল। সন্ধের মধ্যে কেউ আর ফলোয়ার বা মন্তব্যের অভাব বোধ করল না। এখন শর্মারা প্রতি রবিবার ফোনগুলো একটা ঝুড়িতে রেখে দেয়, আর রিয়া বলে ওটাই সপ্তাহের সেরা দিন।",
        "society|2:1|4|q0": "রিয়া তার ফোনে কত স্ক্রিন টাইম দেখেছিল?",
