        "society|2:1|5|title": "সমস্যা কি ফোনটাই?",
        "society|2:1|5|scenario": "হুব্বল্লির কলেজ-ছাত্র কিরণ আর তার পিসি, স্কুলশিক্ষিকা লক্ষ্মী, আলোচনা করে স্মার্টফোন তরুণদের উপকার করে, না ক্ষতি।",
        "society|2:1|5|l0": "কিরণ, দু'ঘণ্টা ধরে তুই ওই স্ক্রিনের দিকে তাকিয়ে আছিস। খেয়াল আছে?",
        "society|2:1|5|l1": "জানি পিসি, কিন্তু আমি শুধু সময় নষ্ট করছি না। কোডিংয়ের একটা লেকচার দেখছি।",
        "society|2:1|5|l2": "ঠিক আছে। কিন্তু আমার অর্ধেক ছাত্রছাত্রী মাঝরাত পর্যন্ত সোশ্যাল মিডিয়ায় থাকে, আর ক্লাসে আসে একদম ক্লান্ত হয়ে।",
        "society|2:1|5|l3": "সেটা সত্যি। কিছু অ্যাপ এমনভাবেই বানানো যাতে তুমি স্ক্রল করেই যাও, আর নোটিফিকেশন কখনও থামে না।",
        "society|2:1|5|l4": "তাহলে তোর কি মনে হয় স্মার্টফোনে উপকারের চেয়ে ক্ষতি বেশি?",
        "society|2:1|5|l5": "তা নয়। গত মাসে আমি ফোন থেকেই পরীক্ষার ফি দিয়েছি, ট্রেনের টিকিট কেটেছি আর একটা পার্ট-টাইম চাকরিও পেয়েছি।",
        "society|2:1|5|l6": "এর বিরুদ্ধে কিছু বলার নেই। তোর ঠাকুমা তো এখন রোজ পুনেতে তাঁর বোনকে ভিডিও কল করেন।",
        "society|2:1|5|l7": "ঠিক তাই। ফোন তো শুধু একটা যন্ত্র। সমস্যা শুরু হয় যখন আমরা ওটা নামিয়ে রাখতে পারি না।",
        "society|2:1|5|l8": "তাহলে একটা চ্যালেঞ্জ: আজ রাতে পড়ার সময় ফোনটা অন্য ঘরে রেখে দে।",
        "society|2:1|5|l9": "রাজি। কিন্তু তোমাকেও খাওয়ার সময় ফ্যামিলি গ্রুপ দেখা বন্ধ করতে হবে!",
