        "society|3:1|1|p0": "হোসুর রোডের যানজটে আজ আবার আমার এক ঘণ্টা দেরি হল।",
        "society|3:1|1|p1": "বাস আর মেট্রোয় আমার রোজের যাতায়াতে যেতে-আসতে নব্বই মিনিট করে লাগে।",
        "society|3:1|1|p2": "বেঙ্গালুরুতে ভাড়া এত বেশি যে আমরা চারজন একটা ফ্ল্যাট ভাগ করে থাকি।",
        "society|3:1|1|p3": "আওয়াজ থেকে বাঁচতে আমরা একটা শান্ত শহরতলিতে চলে গেছি।",
        "society|3:1|1|p4": "নতুন উড়ালপুলের জন্য অফিসে যেতে আমার কুড়ি মিনিট কম লাগছে।",
