        "society|3:1|3|p1": "আমাদের গ্রামে কেউ বাড়ি বানালে গোটা সমাজ সাহায্য করে।",
        "society|3:1|3|p2": "সবচেয়ে কাছের হাসপাতাল চল্লিশ কিলোমিটার দূরে, তাই এখানে আরও ভালো সুযোগ-সুবিধা দরকার।",
        "society|3:1|3|p3": "পঞ্চায়েত শেষমেশ বাসস্টপ যাওয়ার রাস্তাটা সারিয়েছে।",
        "society|3:1|3|p4": "ফসল তোলার পর গোটা গ্রাম গানবাজনা আর খাওয়াদাওয়া করে উৎসব করে।",
        "society|3:1|4|title": "দুই ঘরের মাঝে",
        "society|3:1|4|text": "পাঁচ বছর আগে সন্তোষ কলবুর্গির কাছে তার গ্রাম ছেড়ে কাজের জন্য বেঙ্গালুরুতে চলে এসেছিল। এখন সে শহরতলির একটা ছোট ফ্ল্যাটে থাকে, আর মাইনের অর্ধেক ভাড়া দেয়। রোজের যাতায়াতে তার দিনে দু'ঘণ্টা লাগে, আর যানজট তার ধৈর্যের পরীক্ষা নেয়। তবুও শহর তাকে একটা ভালো চাকরি আর এমন সব সুযোগ-সুবিধা দিয়েছে যা তার গ্রামে কখনও ছিল না। গত মাসে সে ফসল তোলার সময় বাড়ি গিয়েছিল, আর খেয়াল করল মাঠগুলো কত শান্তিপূর্ণ। কিন্তু সে এটাও দেখল যে স্কুলে মাত্র একজন শিক্ষক, আর স্বাস্থ্যকেন্দ্র সপ্তাহে মাত্র দু'দিন খোলে। বাচ্চাদের জন্য একটা কম্পিউটার ক্লাস শুরু করার ব্যাপারে সে পঞ্চায়েতের সঙ্গে কথা বলল। সন্তোষের বিশ্বাস, গ্রামে ভালো সুযোগ-সুবিধা থাকলে শহরে অভিবাসন কমে আসবে।",
        "society|3:1|4|q0": "সন্তোষ মাইনের কতটা ভাড়া দেয়?",
