        "society|3:1|5|scenario": "বেঙ্গালুরুতে বড় হওয়া পূজা আর মান্ড্যার কাছের এক গ্রামের ছেলে, তার বন্ধু মহেশ, তর্ক করে তারা কোথায় থাকতে চাইবে।",
        "society|3:1|5|l0": "মহেশ, সত্যি বলতে মেট্রো আর রাতবিরেতে খাবার ডেলিভারি ছাড়া কোথাও থাকার কথা আমি ভাবতেই পারি না।",
        "society|3:1|5|l1": "আর আমি ভাবতে পারি না শুধু কলেজে পৌঁছনোর জন্য দু'ঘণ্টা যানজটে কাটানোর কথা।",
        "society|3:1|5|l2": "ন্যায্য কথা। কিন্তু শহরে সবকিছু হাতের কাছে: হাসপাতাল, কলেজ, চাকরি।",
        "society|3:1|5|l3": "ঠিক এই কারণেই আমাদের গ্রাম থেকে এত তরুণ চলে যায়। কিন্তু আমাদের এমন কিছু আছে যা তোমাদের নেই।",
        "society|3:1|5|l4": "যেমন? মানে, টাটকা হাওয়া ছাড়া?",
        "society|3:1|5|l5": "সত্যিকারের সমাজ। বাবা যখন অসুস্থ হলেন, প্রতিবেশীরা পালা করে আমাদের খেত দেখাশোনা করেছিলেন।",
        "society|3:1|5|l6": "কী সুন্দর। আমি তো পাশের ফ্ল্যাটের লোকদের নামও জানি না।",
        "society|3:1|5|l7": "ঠিক তাই। শহরে চারপাশে এত লোক, তবুও অনেকে একা বোধ করে।",
        "society|3:1|5|l8": "তাহলে কী থাকলে তুমি গ্রামে থেকে যাবে?",
        "society|3:1|5|l9": "ভালো ইন্টারনেট, একটা ঠিকঠাক হাসপাতাল আর ভালো বাস পরিষেবা। তাহলে আর কখনও ছাড়ব না।",
        "society|3:1|5|q0": "শহরের জীবনের কোন জিনিসটা মহেশের অপছন্দ?",
