        "society|4:1|1|p0": "প্রতি বছর লক্ষ লক্ষ ছাত্রছাত্রী ডাক্তারির প্রবেশিকা পরীক্ষা দেয়।",
        "society|4:1|1|p1": "সিলেবাস এত লম্বা যে ঝালিয়ে নেওয়ার সময়ই প্রায় পাই না।",
        "society|4:1|1|p2": "কিছু পরিবার স্কুলের ফি-র চেয়ে কোচিংয়ে বেশি খরচ করে।",
        "society|4:1|1|p3": "নম্বরের দাম আছে, কিন্তু নম্বরই তোমার গোটা ভবিষ্যৎ ঠিক করে না।",
        "society|4:1|1|p4": "মেধাতালিকায় ওপরের দিকে স্থান পেয়েও ও আত্মীয়দের কাছ থেকে প্রচণ্ড চাপ অনুভব করেছিল।",
