        "society|4:1|2|w4": "দক্ষতা",
        "society|4:1|2|w5": "কাউন্সেলর",
        "society|4:1|3|p0": "লকডাউনের সময় অনলাইন ক্লাস আমাদের সাহায্য করেছিল, কিন্তু আসল ক্লাসরুমের জায়গা কিছুই নিতে পারে না।",
        "society|4:1|3|p1": "ওর পরিবারে ও-ই প্রথম ডিগ্রি পেয়েছে।",
        "society|4:1|3|p2": "রাজ্য সরকারের একটা বৃত্তিতে ওর হস্টেলের খরচ আর বইয়ের দাম উঠে যায়।",
        "society|4:1|3|p3": "শাখা বাছো নিজের ভালো লাগে বলে, বন্ধুরা বেছেছে বলে নয়।",
        "society|4:1|3|p4": "কাউন্সেলর আমাকে বললেন যে নম্বরের মতোই হাতে-কলমে দক্ষতারও দাম আছে।",
        "society|4:1|4|title": "নিজের পথ",
        "society|4:1|4|text": "দাবনগেরের নন্দিনী পিইউ পরীক্ষায় চুরানব্বই শতাংশ নম্বর পেয়েছিল, আর সবাই ভেবেছিল সে ডাক্তার হবে। মা-বাবা তাকে ডাক্তারির প্রবেশিকা পরীক্ষার জন্য একটা দামি কোচিং সেন্টারে ভর্তি করালেন। কিন্তু নন্দিনী তার সব অবসর সময় কলেজ ফেস্টের জন্য পোস্টার আর ছোট ভিডিও বানিয়ে কাটাত। চাপ বাড়তে থাকল, আর প্রতিটা মক টেস্টকে সে ভয় পেতে শুরু করল। শেষে সে কলেজের কাউন্সেলরের সঙ্গে দেখা করল, যিনি মন দিয়ে শুনলেন আর ডিজাইনে ডিগ্রির কথা ভেবে দেখতে সাহায্য করলেন। দুজনে মিলে এমন একটা বৃত্তি খুঁজে পেল যাতে তার বেশিরভাগ খরচ উঠে যাবে। নন্দিনী যখন মা-বাবাকে তার পোর্টফোলিও দেখাল, বাবা অনেকক্ষণ চুপ করে রইলেন। তারপর হেসে বললেন, \"এটাই যদি তোর দক্ষতা হয়, তবে এটাই তোর পথ।\"",
        "society|4:1|4|q0": "সবাই ভেবেছিল নন্দিনী কী হবে?",
