        "society|4:1|5|title": "আমি কী পড়ব?",
        "society|4:1|5|scenario": "ম্যাঙ্গালুরুতে আদিত্য সবে পিইউ পরীক্ষা শেষ করেছে। পুনেতে চাকরি করা তার খুড়তুতো দিদি শ্রুতিকে সে জিজ্ঞেস করে এরপর কী পড়া উচিত।",
        "society|4:1|5|l0": "তা আদিত্য, রেজাল্ট তো বেরিয়ে গেছে। এরপর কী পড়বি ঠিক করেছিস?",
        "society|4:1|5|l1": "ঠিক করিনি। সবাই বলছে ইঞ্জিনিয়ারিং, কিন্তু ওটা আমার ভালো লাগে কি না তাই জানি না।",
        "society|4:1|5|l2": "তাহলে সবাই নিচ্ছে বলে ওটা নিস না। আসলে কোন বিষয়গুলো তোর ভালো লাগে?",
        "society|4:1|5|l3": "সত্যি বলতে, অর্থনীতি। আর কিছু বুঝিয়ে বলতে আমার খুব ভালো লাগে, হয়তো প্রতিবেশীদের বাচ্চাদের পড়াই বলে।",
        "society|4:1|5|l4": "এটা একটা আসল দক্ষতা। অর্থনীতিতে ডিগ্রি, বা শিক্ষকতার কথা ভেবে দেখেছিস?",
        "society|4:1|5|l5": "দেখেছি, কিন্তু বাবার চিন্তা ভালো চাকরি পাওয়া যাবে না। উনি বারবার আমাকে আইআইটি-তে চান্স পাওয়া রাওদের ছেলের সঙ্গে তুলনা করেন।",
        "society|4:1|5|l6": "এ রকম চাপ খুব সাধারণ, কিন্তু চাকরির বাজার দ্রুত বদলাচ্ছে। যোগাযোগ আর সমস্যা সমাধানের দক্ষতার চাহিদা এখন সব জায়গায়।",
        "society|4:1|5|l7": "অনলাইন কোর্সও কি আমার কাজে লাগবে?",
        "society|4:1|5|l8": "অবশ্যই। ডিগ্রির পাশাপাশি ডেটা অ্যানালিসিসের একটা ছোট কোর্স কর, আর কলেজের কাউন্সেলরের সঙ্গে একটা সেশন বুক কর।",
        "society|4:1|5|l9": "ভালো বুদ্ধি। কাউন্সেলরের মুখে শুনলে হয়তো বাবা কথাটা আরও গুরুত্ব দিয়ে নেবেন।",
        "society|4:1|5|q0": "আদিত্যর আসলে কোন বিষয় ভালো লাগে?",
