        "society|5:1|0|w5": "সন্দেহজনক",
        "society|5:1|1|p0": "কাউকে কখনও আপনার ওটিপি বলবেন না, এমনকি কেউ নিজেকে ব্যাংকের লোক বললেও না।",
        "society|5:1|1|p1": "মেসেজটা আসল মনে হচ্ছিল, কিন্তু লিঙ্কটা একটা ভুয়ো ওয়েবসাইটে নিয়ে গেল।",
        "society|5:1|1|p2": "অচেনা কারও কাছ থেকে বড্ড লোভনীয় চাকরির প্রস্তাব এলে সেটা সাধারণত প্রতারণা।",
        "society|5:1|1|p3": "ছোট শহরগুলোতেও ইউপিআই দিয়ে জালিয়াতির ঘটনা হু-হু করে বেড়েছে।",
        "society|5:1|1|p4": "কোনো মেসেজ সন্দেহজনক মনে হলে কিছুতে ক্লিক না করে মুছে ফেলুন।",
        "society|5:1|2|w0": "পাসওয়ার্ড",
        "society|5:1|2|w1": "গোপনীয়তা",
