        "society|5:1|2|w3": "সাইবার অপরাধ",
        "society|5:1|2|w4": "ব্লক করা",
        "society|5:1|2|w5": "যাচাই করা",
        "society|5:1|3|p0": "প্রতিটা অ্যাকাউন্টের জন্য আলাদা পাসওয়ার্ড ব্যবহার করুন, আর কখনও চিরকুটে লিখে রাখবেন না।",
        "society|5:1|3|p1": "এক হ্যাকার ওর ইমেলে ঢুকে ওর সব পরিচিতকে মেসেজ পাঠিয়েছে।",
        "society|5:1|3|p2": "অনলাইনে বাড়ির ছবি পোস্ট করার আগে নিজের গোপনীয়তার কথা ভাবুন।",
        "society|5:1|3|p3": "নম্বরটা ব্লক করুন, তারপর ১৯৩০-এ ফোন করে সাইবার অপরাধের রিপোর্ট করুন।",
        "society|5:1|3|p4": "কোনো ব্যক্তিগত তথ্য দেওয়ার আগে সবসময় ফোনকারীর পরিচয় যাচাই করুন।",
        "society|5:1|4|title": "কেওয়াইসি-র ফোন",
        "society|5:1|4|text": "গত মঙ্গলবার মাইসুরুর অবসরপ্রাপ্ত শিক্ষক ভেঙ্কটেশের কাছে এক লোকের ফোন এল, যে নিজেকে তাঁর ব্যাংকের লোক বলে পরিচয় দিল। ফোনকারী সাবধান করল যে এখনই কেওয়াইসি-র তথ্য আপডেট না করলে তাঁর অ্যাকাউন্ট ব্লক হয়ে যাবে। তারপর একটা লিঙ্ক আর একটা ওটিপি সহ মেসেজ এল। ভেঙ্কটেশ ওটিপিটা জোরে পড়ে শোনাতে যাচ্ছিলেন, তখনই নাতনি আশা তাঁকে থামাল। সে বুঝিয়ে বলল যে ব্যাংক কখনও ফোনে ওটিপি চায় না, আর লিঙ্কটা একটা ভুয়ো ওয়েবসাইটে নিয়ে যায়। দুজনে মিলে সাইবার অপরাধের হেল্পলাইন ১৯৩০-এ ফোন করে নম্বরটার রিপোর্ট করল। পরে তাঁরা ব্যাংকে গেলেন, যেখানে ম্যানেজার নিশ্চিত করলেন যে এটা একটা চেনা প্রতারণা। এখন ভেঙ্কটেশ তাঁর সকালের হাঁটার দলের সবাইকে বলেন ফোন কেটে দিয়ে যাচাই করতে।",
        "society|5:1|4|q0": "ফোনকারী নিজেকে কে বলে দাবি করেছিল?",
