        "society|5:1|5|title": "একটা সন্দেহজনক ফোন",
        "society|5:1|5|scenario": "খবরে ব্যাংকের একটা নতুন প্রতারণার কথা পড়ে ফারহান বেলগাভিতে তার মা শাবানাকে ফোন করে।",
        "society|5:1|5|l0": "আম্মি, আজ কেউ কি তোমাকে ফোন করে ব্যাংক অ্যাকাউন্টের কথা জিজ্ঞেস করেছে?",
        "society|5:1|5|l1": "হ্যাঁ, করেছে তো! খুব ভদ্র এক ছেলে বলল আমার কার্ডের মেয়াদ শেষ হয়ে যাবে, আর একটা নম্বর চাইল।",
        "society|5:1|5|l2": "দোহাই আম্মি, বলো তুমি ওকে নম্বরটা দাওনি।",
        "society|5:1|5|l3": "না, চশমা খুঁজে পাওয়ার আগেই লাইনটা কেটে গেল। কেন, কী হয়েছে?",
        "society|5:1|5|l4": "ওটা প্রতারণা ছিল। ওরা ওটিপি চাইছিল, যাতে তোমার অ্যাকাউন্ট খালি করে দিতে পারে।",
        "society|5:1|5|l5": "হায় আল্লাহ। কিন্তু ও তো আমার নাম আর কার্ডের শেষ চারটে সংখ্যা জানত।",
        "society|5:1|5|l6": "প্রতারকেরা এসব তথ্য অনলাইনে কেনে। এভাবেই ওরা ফোনটাকে আসল বলে মনে করায়।",
        "society|5:1|5|l7": "তাহলে ও আবার ফোন করলে আমি কী করব?",
        "society|5:1|5|l8": "সোজা ফোন কেটে দেবে। ব্যাংক কখনও তোমার ওটিপি বা পিন চাইবে না। সন্দেহ হলে আমাকে ফোন কোরো, বা কার্ডের পেছনের নম্বরে।",
        "society|5:1|5|l9": "ঠিক আছে, বাবা। আমার বিল্ডিংয়ের মহিলাদেরও সাবধান করে দেব। তোর খালা রুখসানা তো সবাইকে বিশ্বাস করে।",
        "society|5:1|5|q0": "ফোনকারী শাবানার কার্ড নিয়ে কী বলেছিল?",
