        "society|6:1|1|p0": "প্রতি রবিবার আমাদের কলেজের স্বেচ্ছাসেবকেরা সরকারি স্কুলে বাচ্চাদের পড়ায়।",
        "society|6:1|1|p1": "ছোট একটা দানেও একটা বাচ্চার স্কুলের বই কেনা যায়।",
        "society|6:1|1|p2": "টাকা দেওয়ার আগে জেনে নিন দাতব্য সংস্থাটা আসলে সেটা কীভাবে খরচ করে।",
        "society|6:1|1|p3": "কাবন পার্কের সাফাই অভিযানে প্রায় দু'শো জন যোগ দিয়েছিলেন।",
        "society|6:1|1|p4": "আমাদের তহবিল সংগ্রহের টাকা জেলার ব্লাড ব্যাংকে যাবে।",
        "society|6:1|2|w0": "বাসিন্দা",
        "society|6:1|2|w1": "বয়স্ক",
        "society|6:1|2|w2": "চাঁদা দেওয়া",
        "society|6:1|2|w3": "সচেতনতা",
        "society|6:1|2|w4": "দয়া",
        "society|6:1|2|w5": "প্রচার অভিযান",
        "society|6:1|3|p0": "আমাদের প্রতিবেশী মিসেস আইয়ার একা থাকেন, তাই আমরা রোজ সন্ধ্যায় ওঁর খোঁজ নিই।",
        "society|6:1|3|p1": "অনেক বয়স্ক মানুষের অনলাইন ব্যাংকিং আর বিল মেটানোয় সাহায্য দরকার।",
        "society|6:1|3|p2": "দারোয়ানের অপারেশনের জন্য সব বাসিন্দাই কিছু না কিছু চাঁদা দিয়েছেন।",
        "society|6:1|3|p3": "প্রচার অভিযানটা গরমকালে জল বাঁচানো নিয়ে সচেতনতা ছড়াচ্ছে।",
        "society|6:1|3|p4": "কারও ব্যাগ বয়ে দেওয়ার মতো একটু দয়াই তার পুরো দিনটা বদলে দিতে পারে।",
        "society|6:1|4|title": "একটা বাসস্টপ, একটা কলোনি",
        "society|6:1|4|text": "ফরিদা যখন হুব্বল্লির একটা নতুন কলোনিতে এল, সে দেখল তার বাড়ির কাছের বাসস্টপটা আবর্জনায় ভরা। অভিযোগ করার বদলে সে একটা নোটিশ টাঙিয়ে প্রতিবেশীদের শনিবার সকালের সাফাই অভিযানে ডাকল। প্রথম সপ্তাহে মাত্র ছ'জন এলেন, কিন্তু দু'ঘণ্টায় তাঁরা পুরো জায়গাটা পরিষ্কার করে ফেললেন। পরের শনিবার কুড়ি জন স্বেচ্ছাসেবক হাজির হলেন, তাঁদের মধ্যে কয়েকজন বয়স্ক বাসিন্দাও ছিলেন, যাঁরা চা আর জলখাবার নিয়ে এসেছিলেন। শিগগিরই দলটা ডাস্টবিন কেনা আর বাস শেল্টার রং করার জন্য ছোট একটা তহবিল সংগ্রহ শুরু করল। এক স্থানীয় দোকানদার উদার হাতে দান করলেন, আর ওয়ার্ডের কাউন্সিলর নিয়মিত আবর্জনা তোলার কথা দিলেন। আজ কলোনির একটা হোয়াটসঅ্যাপ গ্রুপ আছে, যেখানে প্রতিবেশীরা বাজার, হাসপাতালে যাওয়া আর হোমওয়ার্কে একে অপরকে সাহায্য করেন। ফরিদা বলে সাফাই অভিযান ছিল শুধু শুরু; আসল বদল হল, মানুষ অবশেষে একে অপরকে চিনতে পারল।",
        "society|6:1|4|q0": "ফরিদা কোন সমস্যা খেয়াল করল?",
