        "society|6:1|4|q2o3": "কলোনিতে একটা নতুন পার্ক হল",
        "society|6:1|5|title": "ত্রাণ অভিযানের পরিকল্পনা",
        "society|6:1|5|scenario": "উডুপির একটা দাতব্য সংস্থার দুই স্বেচ্ছাসেবক নেহা আর সমীর প্রবল বৃষ্টিতে যাদের বাড়ি ক্ষতিগ্রস্ত হয়েছে, সেই পরিবারগুলোর জন্য উইকেন্ডের একটা অভিযানের পরিকল্পনা করছে।",
        "society|6:1|5|l0": "সমীর, বৃষ্টিতে মালপের কাছে প্রায় চল্লিশটা বাড়ি ক্ষতিগ্রস্ত হয়েছে। এই উইকেন্ডেই আমাদের কিছু করতে হবে।",
        "society|6:1|5|l1": "একমত। পরিবারগুলোর এখন সবচেয়ে বেশি কী দরকার?",
        "society|6:1|5|l2": "শুকনো রেশন, কম্বল, বাচ্চাদের স্কুলব্যাগ আর কিছু দরকারি ওষুধ।",
        "society|6:1|5|l3": "আমি কলেজের স্বেচ্ছাসেবকদের তিনটে আবাসনে সংগ্রহ কেন্দ্র খুলতে বলতে পারি।",
        "society|6:1|5|l4": "বেশ। কিন্তু একটা পরিষ্কার তালিকা শেয়ার করি, নইলে লোকে এমন পুরোনো জামাকাপড় পাঠাবে যা কাজে লাগবে না।",
        "society|6:1|5|l5": "ঠিক। নগদ দানও কি নেব?",
        "society|6:1|5|l6": "শুধু সংস্থার অফিশিয়াল ইউপিআই আইডি দিয়ে, রসিদসহ। লোকের জানা উচিত তাদের টাকা ঠিক কোথায় যাচ্ছে।",
        "society|6:1|5|l7": "তাতে বিশ্বাস তৈরি হবে। আমরা কী কী পৌঁছে দিচ্ছি, তার ছবি দিয়ে রোজ সন্ধ্যায় একটা আপডেট দেব।",
        "society|6:1|5|l8": "চমৎকার। আর মন্দিরের কাছের বয়স্ক দম্পতির একটু খোঁজ নেবে? ওঁদের ছাদ দিয়ে খুব জল পড়ছিল।",
        "society|6:1|5|l9": "কাল সকালে প্রথমেই দু'জন স্বেচ্ছাসেবক আর একটা ত্রিপল নিয়ে ওখানে যাব।",
        "society|6:1|5|q0": "বৃষ্টিতে কতগুলো বাড়ি ক্ষতিগ্রস্ত হয়েছিল?",
